    instance_owner: semio_framework_plugin::ArtifactInstanceOperationOwnerHandle,
    consumed: bool,
}

impl ArtifactCommandWork<EditorApp<Generation2dPlayApp>> for Generation2dContributionsWork {
    fn tool_id(&self) -> &'static str {
        "setContributions"
