//! 🚪️ fem3d → obj — foreign `Serializer<Fem3dSnapshot>` on the framework's `io_mechanism` channel,
//! and REAL geometry: every `FemSolid` outline is triangulated, extruded by its own real
//! `height` (offset by `base_z`), split into tets and reduced to its outward boundary faces — a
//! `SemioMeshSnapshot` (`crate::fem3d_engine::meshing::build_semio_mesh_snapshot`, the same kernel the
//! `🕸️mesh/🧫️fixtures/**/🗿️expected.obj` fixtures pin), then handed to stdio's own tested
//! `SemioMeshToObj` bridge and `encode_obj` grammar — never hand-rolled bytes.
//!
//! `IoFidelity::Lossy`, and that is the honest level: an `.obj` carries vertices and faces. It
//! carries no `FemMaterial`, `FemSection`, `FemSupport`, `FemLoadCase` or analysis settings, and
//! `FemElement::Bar`/`Frame` line members carry no cross-section PROFILE (see the meshing bridge's
//! own doc) so they contribute no geometry — a bar/frame-only model exports a structurally valid,
//! EMPTY `.obj`. There is therefore no inverse: `s.stdio.obj@3.0/*` → `s.fem.fem3d@1/*` is a
//! registered refusal in this subset's `🚪️io/🦀️.rs` `geometry_import` module.

use crate::Fem3dSnapshot;
use semio_framework::io::io_mechanism::Serializer;
use semio_framework::io_schema::{Dialect, IoError, IoFidelity, IoOutcome, IoPayload, IoResult};
use semio_framework_plugin::{ArtifactSerializer, StandardId, SubsetId};
use semio_s_artifact_stdio_obj::standards::v3_0::engine::encode_obj;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::obj::v3_0::any::SemioMeshToObj;

/// 🎯️ The foreign dialect this leaf writes.
pub const OBJ_DIALECT: Dialect = Dialect { artifact_kind: "s.stdio.obj", standard: StandardId("3.0"), subset: SubsetId::ANY };

/// 🧊️ The tetrahedralised solid boundary mesh as real `.obj` text.
pub fn obj_text(from: &Fem3dSnapshot) -> Result<String, IoError> {
    let mesh = crate::fem3d_engine::meshing::build_semio_mesh_snapshot(from);
    let obj = semio_framework_plugin::resolve_ready(SemioMeshToObj::serialize(&mesh)).map_err(|error| IoError { message: format!("fem3d→obj: {error}"), diagnostics: Vec::new() })?;
    Ok(encode_obj(&obj))
}

/// 🧵️ `s.fem.fem3d@1/*` → `s.stdio.obj@3.0/*`.
pub struct Fem3dIntoObj;

impl Serializer<Fem3dSnapshot> for Fem3dIntoObj {
    const INTO: Dialect = OBJ_DIALECT;
    const FIDELITY: IoFidelity = IoFidelity::Lossy;
    async fn serialize(from: &Fem3dSnapshot) -> IoResult<IoPayload> {
        Ok(IoOutcome::clean(IoPayload::Text(obj_text(from)?)))
    }
}

//! 🚪️ fem3d → stl — foreign `Serializer<Fem3dSnapshot>` on the framework's `io_mechanism` channel,
//! and REAL geometry: every `FemSolid` outline is triangulated, extruded by its own real
//! `height` (offset by `base_z`), split into tets and reduced to its outward boundary faces — a
//! `SemioMeshSnapshot` (`crate::fem3d_engine::meshing::build_semio_mesh_snapshot`, the same kernel the
//! `🕸️mesh/🧫️fixtures/**/🧊️expected.stl` fixtures pin), then handed to stdio's own tested
//! `SemioMeshToStl` bridge and `encode_stl_ascii` grammar — never hand-rolled bytes.
//!
//! `IoFidelity::Lossy`, and that is the honest level: an STL solid is a triangle soup. It carries no
//! `FemMaterial`, `FemSection`, `FemSupport`, `FemLoadCase` or analysis settings, and
//! `FemElement::Bar`/`Frame` line members carry no cross-section PROFILE (see the meshing bridge's
//! own doc) so they contribute no geometry — a bar/frame-only model exports a structurally valid,
//! EMPTY `.stl`. There is therefore no inverse: `s.stdio.stl@ascii/*` → `s.fem.fem3d@1/*` is a
//! registered refusal in this subset's `🚪️io/🦀️.rs` `geometry_import` module.

use crate::Fem3dSnapshot;
use semio_framework::io::io_mechanism::Serializer;
use semio_framework::io_schema::{Dialect, IoError, IoFidelity, IoOutcome, IoPayload, IoResult};
use semio_framework_plugin::{ArtifactSerializer, StandardId, SubsetId};
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::stl::v_ascii::any::SemioMeshToStl;
use semio_s_artifact_stdio_stl::standards::v_ascii::engine::encode_stl_ascii;

/// 🎯️ The foreign dialect this leaf writes.
pub const STL_DIALECT: Dialect = Dialect { artifact_kind: "s.stdio.stl", standard: StandardId("ascii"), subset: SubsetId::ANY };

/// 🔺️ The tetrahedralised solid boundary mesh as real ASCII `.stl` text.
pub fn stl_text(from: &Fem3dSnapshot) -> Result<String, IoError> {
    let mesh = crate::fem3d_engine::meshing::build_semio_mesh_snapshot(from);
    let stl = semio_framework_plugin::resolve_ready(SemioMeshToStl::serialize(&mesh)).map_err(|error| IoError { message: format!("fem3d→stl: {error}"), diagnostics: Vec::new() })?;
    Ok(encode_stl_ascii(&stl))
}

/// 🧵️ `s.fem.fem3d@1/*` → `s.stdio.stl@ascii/*`.
pub struct Fem3dIntoStl;

impl Serializer<Fem3dSnapshot> for Fem3dIntoStl {
    const INTO: Dialect = STL_DIALECT;
    const FIDELITY: IoFidelity = IoFidelity::Lossy;
    async fn serialize(from: &Fem3dSnapshot) -> IoResult<IoPayload> {
        Ok(IoOutcome::clean(IoPayload::Text(stl_text(from)?)))
    }
}

//! ⏯️ The read-only `previewEval` tool run (`📋️tool-run-contract.md` §2.4, §3.7): its declaration, the
//! observation and scheduling laws over the retained [`FlowEvalSession`], the surface-owned run link and
//! the run job. The hop and status transport it drives lives in the parent `🧵️preview-eval` module.

use super::*;

/// ⏯️ The tool id of the read-only preview evaluation run on both surfaces.
pub const PREVIEW_EVAL_TOOL_ID: &str = "previewEval";

/// 📜️ Source of record of the run's declaration (`🔣️.json` beside this file).
pub const PREVIEW_EVAL_RUN_RECORD_JSON: &str = include_str!("../🔣️.json");

/// 🪜️ The two stages of one preview evaluation, in declaration order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PreviewEvalRunStage {
    Evaluate,
    Tessellate,
}

impl PreviewEvalRunStage {
    pub const ALL: [Self; 2] = [Self::Evaluate, Self::Tessellate];

    pub fn index(self) -> u16 {
        self as u16
    }

    pub fn id(self) -> &'static str {
        match self {
            Self::Evaluate => "evaluate",
            Self::Tessellate => "tessellate",
        }
    }
}

/// 🔢️ The run's counters, in declaration order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PreviewEvalRunCounter {
    Evaluated,
    Failed,
    Blocked,
    Tessellated,
    Hops,
}

impl PreviewEvalRunCounter {
    pub const ALL: [Self; 5] = [Self::Evaluated, Self::Failed, Self::Blocked, Self::Tessellated, Self::Hops];

    pub fn index(self) -> u16 {
        self as u16
    }

    pub fn id(self) -> &'static str {
        match self {
            Self::Evaluated => "evaluated",
            Self::Failed => "failed",
            Self::Blocked => "blocked",
            Self::Tessellated => "tessellated",
            Self::Hops => "hops",
        }
    }
}

/// 🗒️ Why a node carries its verdict, and the settle steps; `code` is the declaration index.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum PreviewEvalRunReason {
    Queued,
    Computing,
    Evaluated,
    Blocked,
    Failed,
    Tessellating,
    Tessellated,
    MeshDiagnostics,
    MeshMissing,
    Settled,
    SettledWithFailures,
    ExtensionFault,
}

impl PreviewEvalRunReason {
    pub const ALL: [Self; 12] = [Self::Queued, Self::Computing, Self::Evaluated, Self::Blocked, Self::Failed, Self::Tessellating, Self::Tessellated, Self::MeshDiagnostics, Self::MeshMissing, Self::Settled, Self::SettledWithFailures, Self::ExtensionFault];

    pub fn code(self) -> u16 {
        self as u16
    }

    pub fn id(self) -> &'static str {
        match self {
            Self::Queued => "queued",
            Self::Computing => "computing",
            Self::Evaluated => "evaluated",
            Self::Blocked => "blocked",
            Self::Failed => "failed",
            Self::Tessellating => "tessellating",
            Self::Tessellated => "tessellated",
            Self::MeshDiagnostics => "meshDiagnostics",
            Self::MeshMissing => "meshMissing",
            Self::Settled => "settled",
            Self::SettledWithFailures => "settledWithFailures",
            Self::ExtensionFault => "extensionFault",
        }
    }

    pub fn verdict(self) -> ToolRunVerdict {
        match self {
            Self::Queued | Self::Computing | Self::Tessellating => ToolRunVerdict::Testing,
            Self::Evaluated | Self::Tessellated | Self::Settled => ToolRunVerdict::Success,
            Self::Blocked | Self::MeshDiagnostics | Self::MeshMissing | Self::SettledWithFailures => ToolRunVerdict::Warning,
            Self::Failed | Self::ExtensionFault => ToolRunVerdict::Danger,
        }
    }
}

fn preview_eval_run_record() -> serde_json::Value {
    serde_json::from_str(PREVIEW_EVAL_RUN_RECORD_JSON).expect("the preview evaluation run record is valid JSON")
}

/// ⏯️ The run declaration, deserialized from the source of record: read-only; a document or settings
/// change restarts it, because an evaluation of a moved graph is a different result and the session's
/// incremental baseline makes the restart cost only the dirty nodes.
pub fn preview_eval_run_definition() -> ToolRunDefinition {
    serde_json::from_value(preview_eval_run_record()["definition"].clone()).expect("the preview evaluation run definition matches the tool run schema")
}

/// 🛠️ The `previewEval` tool: declared on the app, referenced by no mode, started by the surface.
pub fn preview_eval_tool_definition() -> ToolDefinition {
    let record = preview_eval_run_record();
    let label: LocalizedLabel = serde_json::from_value(record["label"].clone()).expect("the preview evaluation tool label is a localized label");
    let icon = record["iconId"].as_str().unwrap_or_default().to_string();
    ToolDefinition { run: Some(preview_eval_run_definition()), ..semio_framework_plugin::resolve_ready(ToolDefinition::new(PREVIEW_EVAL_TOOL_ID, label, icon.as_str())) }
}

/// 🪪️ The trace entity of one flow node: FNV-1a 64 of its id's UTF-8 bytes, so a node graph in any
/// language highlights the node a trace record names without a lookup table.
pub fn preview_eval_node_entity(node_id: &str) -> u64 {
    node_id.bytes().fold(0xcbf2_9ce4_8422_2325, |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x0000_0100_0000_01b3))
}

/// 🧊️ What the session holds for one preview geometry handle.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PreviewEvalMeshState {
    Ready,
    Diagnostics,
    Pending,
}

/// 🔎️ One observation of the evaluation: every node's reason plus the preview mesh census.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct PreviewEvalObservation {
    pub nodes: BTreeMap<String, PreviewEvalRunReason>,
    pub meshes: u64,
    pub tessellated: u64,
}

impl PreviewEvalObservation {
    pub fn count(&self, reason: PreviewEvalRunReason) -> u64 {
        self.nodes.values().filter(|candidate| **candidate == reason).count() as u64
    }

    /// 🪜️ The stage the run is IN: nodes are still being evaluated while any of them is queued or
    /// computing, or while the evaluation has produced no preview mesh at all; anything else has
    /// reached tessellation and stays there.
    ///
    /// ⚖️ `meshes == tessellated` used to answer `Evaluate`, which is true of a run that has not
    /// reached a mesh yet (`0 == 0`) and equally true of a run whose every mesh is DONE — so the
    /// stage fell back to the first one at the exact moment the run converged, and the Tool runs
    /// pill read `Finalized · Evaluating nodes (1/2)` over a finished evaluation on 6027 at 23:06
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END). A terminal run shows its TERMINAL stage.
    pub fn stage(&self) -> PreviewEvalRunStage {
        if self.nodes.values().any(|reason| matches!(reason, PreviewEvalRunReason::Queued | PreviewEvalRunReason::Computing)) || self.meshes == 0 {
            PreviewEvalRunStage::Evaluate
        } else {
            PreviewEvalRunStage::Tessellate
        }
    }

    /// 📊️ Settled nodes plus tessellated meshes of all nodes plus all known meshes.
    pub fn progress(&self) -> (u64, u64) {
        let settled = self.nodes.values().filter(|reason| !matches!(reason, PreviewEvalRunReason::Queued | PreviewEvalRunReason::Computing)).count() as u64;
        (settled + self.tessellated, self.nodes.len() as u64 + self.meshes)
    }
}

/// 🔎️ Reads one observation off the session's published per-widget status and evaluation — pure, so
/// the verdict law is a fixture table. A preview widget that evaluated refines into its meshes:
/// diagnostics warn, all ready succeed, otherwise it is still tessellating, or missing once `settled`.
///
/// ⚖️ The census counts EVERY geometry-bearing channel item, because the preview publishes exactly one
/// mesh per such item ([`preview_mesh_role`]). An inline point or vector marker carries no kernel
/// handle — [`collect_preview_channel_items`] mints it with an empty one and [`point_marker_mesh`]
/// builds it without a kernel round-trip — so it is READY the moment it is observed. Skipping the
/// handle-less items made the pill disagree with the geometry on screen: the hex column delivers a
/// wire, a vector and a solid and the pill counted `2 meshes tessellated` on 6027 at 23:06
/// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
pub fn observe_preview_eval(status_json: &str, eval_json: &str, preview_widget_ids: &[String], mesh_state: impl Fn(&str) -> PreviewEvalMeshState, settled: bool) -> PreviewEvalObservation {
    let mut observation = PreviewEvalObservation::default();
    let Ok(status) = semio_framework_pack_json::parse(status_json, semio_framework_pack_json::JsonMemberPolicy::Reject) else { return observation };
    let Some(widgets) = status.as_object() else { return observation };
    let eval = semio_framework_pack_json::parse(eval_json, semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap_or_else(|_| semio_framework_pack_json::Value::Object(semio_framework_pack_json::Object::new()));
    for (widget_id, entry) in widgets.iter() {
        let mut reason = match entry.get("status").and_then(semio_framework_pack_json::Value::as_str) {
            Some("ok") => PreviewEvalRunReason::Evaluated,
            Some("computing") => PreviewEvalRunReason::Computing,
            Some("error") => PreviewEvalRunReason::Failed,
            Some("blocked") => PreviewEvalRunReason::Blocked,
            _ => PreviewEvalRunReason::Queued,
        };
        if reason == PreviewEvalRunReason::Evaluated && preview_widget_ids.iter().any(|id| id == widget_id) {
            let states: Vec<PreviewEvalMeshState> = preview_channel_items_for_widget(&eval, widget_id).into_iter().map(|item| if item.handle.is_empty() { PreviewEvalMeshState::Ready } else { mesh_state(&item.handle) }).collect();
            observation.meshes += states.len() as u64;
            observation.tessellated += states.iter().filter(|state| **state == PreviewEvalMeshState::Ready).count() as u64;
            reason = if states.is_empty() {
                reason
            } else if states.contains(&PreviewEvalMeshState::Diagnostics) {
                PreviewEvalRunReason::MeshDiagnostics
            } else if states.iter().all(|state| *state == PreviewEvalMeshState::Ready) {
                PreviewEvalRunReason::Tessellated
            } else if settled {
                PreviewEvalRunReason::MeshMissing
            } else {
                PreviewEvalRunReason::Tessellating
            };
        }
        observation.nodes.insert(widget_id.to_string(), reason);
    }
    observation
}

fn preview_eval_mesh_state(session: &FlowEvalSession, handle: &str) -> PreviewEvalMeshState {
    if session.preview_diagnostics(handle).is_some() {
        PreviewEvalMeshState::Diagnostics
    } else if session.preview_mesh_pack(handle).is_some() {
        PreviewEvalMeshState::Ready
    } else {
        PreviewEvalMeshState::Pending
    }
}

/// 🦶️ What the run does next with the attached preview windows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PreviewEvalHop {
    /// ⏱️ The window at this roster index owes an evaluation hop nothing is chasing.
    Dispatch(usize),
    /// ⏳️ A dispatched hop or an extension answer is still outstanding.
    Wait,
    /// 🏁️ No window owes or awaits anything.
    Settled,
}

/// 🦶️ The scheduling law, read off the per-window latches the hops and answers maintain.
pub fn next_preview_eval_hop(session: &FlowEvalSession, windows: &[(String, &'static str)]) -> PreviewEvalHop {
    if let Some(index) = windows.iter().position(|(window_id, _)| session.window_tick_owed(window_id)) {
        return PreviewEvalHop::Dispatch(index);
    }
    if windows.iter().any(|(window_id, _)| session.window_tick_is_armed(window_id) || session.window_extensions_in_flight(window_id) > 0) {
        PreviewEvalHop::Wait
    } else {
        PreviewEvalHop::Settled
    }
}

/// 🔗 The surface-owned half of the run, held by the instance operation owner beside the session: the
/// attached preview roster the job schedules over, the live job's port its folds wake, and the run
/// generation the last evaluation settled under.
#[derive(Default)]
pub struct PreviewEvalRunLink {
    pub(crate) windows: Vec<(String, &'static str)>,
    pub(crate) port: Option<ToolRunJobPort>,
    pub(crate) settled: Option<(u64, u32)>,
    pub(crate) restart_owed: bool,
    /// ⏯️ The run action this link has asked for and not yet seen answered, with the run identity it
    /// named. A run action is a REQUEST — the host takes several `pending_effects` polls to turn one
    /// into a run state — so without this latch a surface re-reads the same unpaid debt on every
    /// refresh and asks again, which is how one quiet boot spent three starts in 500 ms and one busy
    /// session spent 1 053. The identity is what keeps the latch from becoming a deadlock: an action
    /// that named a generation the ledger has already moved past is refused as stale, and only a
    /// request addressed to the CURRENT identity is still worth waiting for
    /// (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`).
    pub(crate) requested: Option<(PreviewEvalRunRequest, Option<(u64, u32)>)>,
    /// 🧹️ The run whose job currently OWNS this link. A start retires the previous entry, so the old
    /// job's `close_step` runs AFTER the new job has already installed its own port and reset
    /// [`Self::settled`] — and a closing job that reads the new run's markers as its own quiesces the
    /// session it was never running, which paints the fresh preview `cancelled` and empties it. The
    /// closing job compares its own run id against this before touching anything
    /// (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`).
    pub(crate) job_run: Option<u64>,
    /// 🧾️ The applied document-edit stack this link last owed the previews for
    /// ([`super::applied_document_edits_digest`]). `None` until the first poll, so a boot owes nothing
    /// extra; a move owes every attached window exactly one fresh evaluation, whichever route moved it.
    pub(crate) applied_edits: Option<u64>,
}

/// ⏯️ A run action a surface has asked the host for, and the reading of the document's `ToolRunView`
/// that answers it. Deliberately not "the view changed": an unrelated generation bump would clear a
/// latch whose request is still outstanding, and the point of the latch is to survive exactly that.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum PreviewEvalRunRequest {
    /// ▶️ Answered once the view reports a run that is no longer startable.
    Start,
    /// 🏁️ Answered once the view reports the complete run it named is complete no longer.
    Finalize,
}

impl PreviewEvalRunRequest {
    fn answered_by(self, state: Option<ToolRunState>) -> bool {
        match self {
            Self::Start => !matches!(state, None | Some(ToolRunState::Finalized | ToolRunState::Aborted | ToolRunState::Faulted)),
            Self::Finalize => state != Some(ToolRunState::Complete),
        }
    }
}

impl PreviewEvalRunLink {
    pub fn windows(&self) -> &[(String, &'static str)] {
        &self.windows
    }

    /// ⏰️ Wakes the live run job, if any — every fold that changed the session calls it.
    pub fn wake(&self) {
        if let Some(port) = self.port.as_ref() {
            port.wake();
        }
    }

    /// 🧹️ Whether the job of `run` is still the one this link belongs to.
    pub(crate) fn owned_by(&self, run: u64) -> bool {
        self.job_run == Some(run)
    }

    fn attach_windows(&mut self, windows: &[(&str, &'static str)]) {
        if self.windows.len() != windows.len() || self.windows.iter().zip(windows).any(|(held, attached)| held.0 != attached.0 || held.1 != attached.1) {
            self.windows = windows.iter().map(|(window_id, kind)| ((*window_id).to_string(), *kind)).collect();
        }
    }
}

/// 🧳️ What the run needs from a surface's retained instance operation owner.
pub trait PreviewEvalRunOwner: std::any::Any + Send {
    fn preview_eval_parts(&mut self) -> Option<(&mut FlowEvalSession, &mut PreviewEvalRunLink)>;
}

pub(crate) fn run_action_effect(action: &str, args: dsl::DslValue) -> Effect {
    Effect::DispatchAction { req: semio_framework_plugin::RequestId(PREVIEW_EVAL_HOP_REQUEST), action: action.into(), args: Some(args), delay_ms: 0 }
}

/// 🚦️ What a surface's `pending_effects` owes the run for the attached `windows`: start a run once a
/// window owes an evaluation, finalize a complete run whose document, settings or contributions moved
/// on (the next poll then starts the fresh one), and wake a live run so it sees a changed roster. An
/// aborted run stays down until a gesture owes its windows again.
pub fn preview_eval_run_effects(session: &mut FlowEvalSession, link: &mut PreviewEvalRunLink, windows: &[(&str, &'static str)], run: Option<&ToolRunView>, servable: bool, applied_edits: u64) -> Vec<Effect> {
    session.retain_window_tick_latches(&windows.iter().map(|(window_id, _)| *window_id).collect::<Vec<_>>());
    link.attach_windows(windows);
    link.wake();
    if windows.is_empty() || !servable {
        link.applied_edits = Some(applied_edits);
        return Vec::new();
    }
    // 🧾️ The document moved by a route this app does not handle — an undo, a redo, a revert, a
    // checkpoint checkout (`super::applied_document_edits_digest`).
    //
    // 🔒️ The DEBT is recorded and a live run woken; the request latch is deliberately NOT released,
    // which is what `owe_attached_previews` does and why this does not call it. A gesture that moved
    // the stack has already asked for its run on its own emit, and releasing the latch here made the
    // very next poll ask for a second one — `a_shell_dispatched_example_switch_republishes_both_windows_and_rearms_the_eval_chain`
    // caught exactly that ("the refresh poll must ask for no second run"). With the latch held, a
    // gesture's own ask stands and a history verb — which asked for nothing — is served by the ladder
    // below on this same poll.
    if link.applied_edits.is_some_and(|held| held != applied_edits) {
        for (window_id, _) in windows {
            session.note_window_tick_outcome(window_id, true);
        }
        link.wake();
    }
    link.applied_edits = Some(applied_edits);
    let owed = windows.iter().any(|(window_id, _)| session.window_tick_owed(window_id));
    let run = run.filter(|run| run.tool_id == PREVIEW_EVAL_TOOL_ID);
    // ⏯️ A start and a finalize are REQUESTS, not state changes: the document's run view keeps
    // answering what it answered before until the host has turned one into a run state. Asking once
    // per REFRESH instead of once per ANSWER is what spent three starts in 500 ms on a quiet boot and
    // 1 053 in one busy session — so the link holds its request until the view ANSWERS it, and a
    // landed gesture (`owe_attached_previews`) is the one other thing that releases it, which bounds
    // the ask at one per gesture and keeps a dropped request from wedging the preview for good
    // (`📓️preview-rearm-after-inspector-edit-2026-09-14.md`).
    let state = run.map(|run| run.state);
    let identity = run.map(|run| (run.identity.id.run, run.identity.generation));
    // 🔓️ A request the ledger has already moved past is refused as stale, so waiting on it forever is a
    // deadlock; a request that named NO identity (a gesture's own start, taken before any poll) is
    // released by its answer alone.
    if link.requested.is_some_and(|(requested, asked)| requested.answered_by(state) || asked.is_some_and(|asked| Some(asked) != identity)) {
        link.requested = None;
    }
    if link.requested.is_some() {
        return Vec::new();
    }
    let (request, effects) = match state {
        Some(ToolRunState::Complete) => {
            let run = run.expect("a complete run is present");
            // 🏁️ A complete run is FINALIZED as soon as it is seen, owed or not. `Complete` means "the job
            // is done and the run awaits its finalize", and a run left standing in it makes every later
            // `toolRunStart` a no-op against the run already there — which is exactly how an inspector
            // edit could owe two windows a perfect debt and still never re-evaluate. Pairing the finalize
            // with the start in one poll does not help: the host schedules a poll's effects
            // independently, so the start lands while the run is still complete and is dropped again
            // (measured on 6018, `📓️preview-rearm-after-inspector-edit-2026-09-14.md`). Finalizing
            // promptly leaves the surface in the ONE state from which a single start — a gesture's own,
            // or the next poll's — really starts a run.
            link.restart_owed = owed;
            (Some((PreviewEvalRunRequest::Finalize, identity)), vec![run_action_effect(TOOL_RUN_FINALIZE_ACTION_ID, dsl::DslValue::object([(TOOL_RUN_ARG_RUN_ID.to_string(), dsl::DslValue::String(run.identity.id.run.to_string())), (TOOL_RUN_ARG_GENERATION.to_string(), dsl::DslValue::uint(u64::from(run.identity.generation)))]))])
        }
        None | Some(ToolRunState::Finalized | ToolRunState::Aborted | ToolRunState::Faulted) if owed || link.restart_owed => {
            link.restart_owed = false;
            (Some((PreviewEvalRunRequest::Start, identity)), vec![run_action_effect(TOOL_RUN_START_ACTION_ID, dsl::DslValue::object([(TOOL_RUN_ARG_TOOL_ID.to_string(), dsl::DslValue::String(PREVIEW_EVAL_TOOL_ID.into()))]))])
        }
        _ => (None, Vec::new()),
    };
    link.requested = request;
    effects
}

/// 🧯️ Whether the session still holds work a closing run must release.
fn preview_eval_work_outstanding(session: &FlowEvalSession, windows: &[(String, &'static str)]) -> bool {
    session.extensions_in_flight() > 0 || windows.iter().any(|(window_id, _)| session.window_tick_is_armed(window_id)) || session.preview_tessellate_status().is_cancellable() || session.preview_eval_status().is_cancellable()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PreviewEvalRunPhase {
    Running,
    Complete,
}

/// ⏯️ The `previewEval` run job (contract §3.7). One unit of fuel is one evaluation hop handed to the
/// host; between hops the job waits on its port, so a paused run's single step advances exactly one
/// hop and a run waiting on the geometry kernel costs no turn. Each step re-observes the session and
/// upserts a trace record for every node whose reason changed; the run completes once no attached
/// window owes or awaits anything. Closing quiesces the session and releases outstanding kernel work.
pub struct PreviewEvalRunJob<O: PreviewEvalRunOwner> {
    owner: ArtifactInstanceOperationOwnerHandle,
    port: ToolRunJobPort,
    identity: ToolRunIdentity,
    writer: ToolRunTickWriter,
    preview_widget_ids: Vec<String>,
    observed: BTreeMap<String, PreviewEvalRunReason>,
    observation: PreviewEvalObservation,
    hops: u64,
    faulted: bool,
    phase: PreviewEvalRunPhase,
    closing: bool,
    released: bool,
    owner_type: std::marker::PhantomData<fn() -> O>,
}

impl<O: PreviewEvalRunOwner> PreviewEvalRunJob<O> {
    /// 🧳️ Attaches the job's port to the owner's link and owes every attached window one evaluation, so a
    /// fresh or restarted run always evaluates the document it was started on.
    pub fn new(owner: ArtifactInstanceOperationOwnerHandle, port: ToolRunJobPort, identity: ToolRunIdentity, preview_widget_ids: Vec<String>) -> Result<Self, Fault> {
        owner.with_mut::<O, _>(|held| {
            let (session, link) = held.preview_eval_parts().ok_or_else(|| Fault::from("generation3d-preview-eval-session-closing"))?;
            for (window_id, _) in &link.windows {
                session.note_window_tick_outcome(window_id, true);
            }
            link.port = Some(port.clone());
            link.settled = None;
            link.job_run = Some(identity.id.run);
            Ok(())
        })?;
        Ok(Self {
            owner,
            port,
            identity,
            writer: ToolRunTickWriter::new(identity),
            preview_widget_ids,
            observed: BTreeMap::new(),
            observation: PreviewEvalObservation::default(),
            hops: 0,
            faulted: false,
            phase: PreviewEvalRunPhase::Running,
            closing: false,
            released: false,
            owner_type: std::marker::PhantomData,
        })
    }

    fn record(&mut self, observation: PreviewEvalObservation) {
        for key in self.observed.keys().filter(|widget_id| !observation.nodes.contains_key(*widget_id)).map(|widget_id| preview_eval_node_entity(widget_id)).collect::<Vec<_>>() {
            self.writer.retire(key);
        }
        for (widget_id, reason) in &observation.nodes {
            if self.observed.get(widget_id) != Some(reason) {
                let entity = preview_eval_node_entity(widget_id);
                self.writer.upsert(entity, reason.verdict(), reason.code(), ToolRunTraceSubject::Entity { entity });
            }
        }
        self.observed.clone_from(&observation.nodes);
        self.observation = observation;
    }

    fn progress(&self, state: ToolRunState) -> ToolRunProgress {
        let (completed, total) = self.observation.progress();
        let values = [
            self.observation.count(PreviewEvalRunReason::Evaluated) + self.observation.count(PreviewEvalRunReason::Tessellated) + self.observation.count(PreviewEvalRunReason::Tessellating) + self.observation.count(PreviewEvalRunReason::MeshDiagnostics) + self.observation.count(PreviewEvalRunReason::MeshMissing),
            self.observation.count(PreviewEvalRunReason::Failed),
            self.observation.count(PreviewEvalRunReason::Blocked),
            self.observation.tessellated,
            self.hops,
        ];
        ToolRunProgress {
            identity: self.identity,
            sequence: 0,
            state,
            stage: self.observation.stage().index(),
            completed,
            total: Some(total),
            counters: PreviewEvalRunCounter::ALL.iter().zip(values).map(|(counter, value)| ToolRunCounter { counter: counter.index(), value }).collect(),
            units_per_second: 0.0,
            conflicts: 0,
            steps: ToolRunStepRing::new(),
        }
    }

    fn settle(&mut self) {
        let failed = self.observation.count(PreviewEvalRunReason::Failed) + self.observation.count(PreviewEvalRunReason::Blocked) + self.observation.count(PreviewEvalRunReason::MeshMissing) + self.observation.count(PreviewEvalRunReason::MeshDiagnostics);
        let stage = self.observation.stage().index();
        let nodes = self.observation.nodes.len() as u64;
        let _ = if failed > 0 {
            self.writer.step(ToolRunStepKind::Warning, stage, PreviewEvalRunReason::SettledWithFailures.code(), None, &[ToolRunStepArg::Unsigned(failed), ToolRunStepArg::Unsigned(nodes)])
        } else {
            self.writer.step(ToolRunStepKind::Success, stage, PreviewEvalRunReason::Settled.code(), None, &[ToolRunStepArg::Unsigned(nodes), ToolRunStepArg::Unsigned(self.observation.tessellated)])
        };
        self.phase = PreviewEvalRunPhase::Complete;
    }

    fn emit(&mut self, cx: &mut StepContext<'_>, state: ToolRunState) -> StepOutcome {
        self.writer.progress(self.progress(state));
        let payload = self.writer.finish().and_then(|tick| tick.encode().ok()).and_then(|bytes| cx.payload_from_bytes(JobPayloadStream::Preview, &bytes).map_err(|rejected| drop(rejected.into_source())).ok());
        payload.map_or_else(|| StepOutcome::Fault(JobFault { detail: RetainedJobPayload::empty(JobPayloadStream::Fault) }), StepOutcome::PreviewReady)
    }
}

impl<O: PreviewEvalRunOwner> InteractiveJob for PreviewEvalRunJob<O> {
    fn step(&mut self, cx: &mut StepContext<'_>) -> StepOutcome {
        if self.closing || cx.is_cancelled() {
            return StepOutcome::Cancelled;
        }
        if self.phase == PreviewEvalRunPhase::Complete {
            return StepOutcome::Complete(CommitCandidate { state: RetainedJobPayload::empty(JobPayloadStream::CommitState), output: RetainedJobPayload::empty(JobPayloadStream::CommitOutput) });
        }
        let (port, preview_widget_ids, identity) = (self.port.clone(), &self.preview_widget_ids, self.identity);
        let turn = self.owner.with_mut::<O, _>(|held| {
            let (session, link) = held.preview_eval_parts().ok_or_else(|| Fault::from("generation3d-preview-eval-session-closing"))?;
            let hop = next_preview_eval_hop(session, &link.windows);
            match hop {
                PreviewEvalHop::Dispatch(index) => {
                    let (window_id, kind) = &link.windows[index];
                    if session.arm_window_tick(window_id) {
                        port.dispatch(tick_effect(window_id, kind));
                    }
                }
                PreviewEvalHop::Wait => port.wait(),
                PreviewEvalHop::Settled => link.settled = Some((identity.id.run, identity.generation)),
            }
            let observation = observe_preview_eval(session.status_json(), session.eval_json(), preview_widget_ids, |handle| preview_eval_mesh_state(session, handle), hop == PreviewEvalHop::Settled);
            Ok((hop, observation, session.extension_evaluate_fault().is_some()))
        });
        let (hop, observation, extension_fault) = match turn {
            Ok(turn) => turn,
            Err(fault) if fault.code.0 == "interactive-job.instance-owner-busy" => return StepOutcome::Yield,
            Err(_) => return StepOutcome::Fault(JobFault { detail: RetainedJobPayload::empty(JobPayloadStream::Fault) }),
        };
        self.record(observation);
        if extension_fault && !self.faulted {
            let _ = self.writer.step(ToolRunStepKind::Danger, self.observation.stage().index(), PreviewEvalRunReason::ExtensionFault.code(), None, &[]);
        }
        self.faulted = extension_fault;
        match hop {
            PreviewEvalHop::Dispatch(_) => {
                self.hops += 1;
                cx.consume_fuel(1);
                self.emit(cx, ToolRunState::Running)
            }
            PreviewEvalHop::Settled => {
                self.settle();
                self.emit(cx, ToolRunState::Complete)
            }
            PreviewEvalHop::Wait if self.writer.is_empty() => StepOutcome::Yield,
            PreviewEvalHop::Wait => self.emit(cx, ToolRunState::Running),
        }
    }

    fn begin_close(&mut self) {
        self.closing = true;
    }

    fn close_step(&mut self, maximum_items: usize, _maximum_bytes: usize) -> InteractiveJobCloseStep {
        self.closing = true;
        if self.released {
            return InteractiveJobCloseStep::Complete;
        }
        if maximum_items == 0 {
            return InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
        }
        let (port, identity) = (self.port.clone(), self.identity);
        let released = self.owner.with_mut::<O, _>(|held| {
            let Some((session, link)) = held.preview_eval_parts() else { return Ok(()) };
            if !link.owned_by(identity.id.run) {
                return Ok(());
            }
            link.port = None;
            link.job_run = None;
            if link.settled.is_some() {
                return Ok(());
            }
            let outstanding = preview_eval_work_outstanding(session, &link.windows);
            let first = link.windows.first().cloned();
            session.cancel_preview_evaluation(first.as_ref().map_or("", |(window_id, _)| window_id.as_str()));
            if let (true, Some((window_id, kind))) = (outstanding, first) {
                port.dispatch(release_effect(&window_id, kind));
            }
            Ok(())
        });
        match released {
            Err(fault) if fault.code.0 == "interactive-job.instance-owner-busy" => InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 },
            _ => {
                self.released = true;
                InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 }
            }
        }
    }

    fn terminal_is_empty(&self) -> bool {
        self.closing && self.released
    }
}

//! 🧬️ Shooting artifact schema — every field of the artifact with its state class.

use crate::{ShootingEmblemChild, ShootingSnapshot};
use dsl::json;
use semio_framework_pack_json::Value;
use schema::ArtifactSchema;
use semio_s_artifact_stdio_semio::standards::v1::subsets::base::schema::geometry::{SemioPoint2, SemioRgba, SemioTransform};
use semio_s_artifact_stdio_semio::standards::v1::subsets::drawing::schema::snapshot::{DrawCanvas, DrawLayer, DrawNode, DrawStyle, PathSegment, SemioDrawingSnapshot, STDIO_SEMIODRAWING_DOCUMENT_SCHEMA};
use semio_s_artifact_stdio_svg::schema::snapshot::write_svg_xml;
use semio_s_artifact_stdio_svg::SvgSnapshot;

//#region 🔖️Artifact
/// 🧬️ shooting document artifact state.
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, ArtifactSchema)]
#[value(rename_all = "camelCase")]
#[artifact_schema(id = "s.shooting.shooting")]
pub struct ShootingArtifact {
    #[state(artifact)]
    pub schema: String,
    #[state(artifact)]
    pub assets: Vec<ShootingAsset>,
    #[state(artifact)]
    pub saved_cameras: Vec<ShootingSavedCamera>,
    #[state(artifact)]
    pub scene: ShootingSceneLighting,
    #[state(artifact)]
    pub shots: Vec<ShootingShot>,
    #[state(artifact)]
    pub active_shot_id: String,
    #[state(artifact)]
    pub active_asset_id: String,
    /// 🕸️ Composed `s.stdio.semio.image` child mirror — see `ShootingSnapshot::emblem`'s doc comment.
    #[state(artifact)]
    #[child(kind = "s.stdio.semio")]
    pub emblem: Option<ShootingEmblemChild>,
}
//#endregion 🔖️Artifact

//#region 🔖️Conversions
impl Default for ShootingArtifact {
    fn default() -> Self {
        Self { schema: crate::SHOOTING_DOCUMENT_SCHEMA.into(), assets: Vec::new(), saved_cameras: Vec::new(), scene: ShootingSceneLighting::default(), shots: Vec::new(), active_shot_id: String::new(), active_asset_id: String::new(), emblem: None }
    }
}

impl ShootingArtifact {
    /// 📸️ Persisted subset.
    pub fn to_snapshot(&self) -> ShootingSnapshot {
        ShootingSnapshot {
            schema: self.schema.clone(),
            assets: self.assets.clone(),
            saved_cameras: self.saved_cameras.clone(),
            scene: self.scene.clone(),
            shots: self.shots.clone(),
            active_shot_id: self.active_shot_id.clone(),
            active_asset_id: self.active_asset_id.clone(),
            emblem: self.emblem.clone(),
        }
    }

    /// 🧬️ Builds the document artifact from its snapshot.
    pub fn from_snapshot(snapshot: ShootingSnapshot) -> Self {
        Self {
            schema: snapshot.schema,
            assets: snapshot.assets,
            saved_cameras: snapshot.saved_cameras,
            scene: snapshot.scene,
            shots: snapshot.shots,
            active_shot_id: snapshot.active_shot_id,
            active_asset_id: snapshot.active_asset_id,
            emblem: snapshot.emblem,

        }
    }

    /// 🔄 Writes persistent fields from a snapshot into this artifact.
    pub fn set_snapshot(&mut self, snapshot: ShootingSnapshot) {
        self.schema = snapshot.schema;
        self.assets = snapshot.assets;
        self.saved_cameras = snapshot.saved_cameras;
        self.scene = snapshot.scene;
        self.shots = snapshot.shots;
        self.active_shot_id = snapshot.active_shot_id;
        self.active_asset_id = snapshot.active_asset_id;
        self.emblem = snapshot.emblem;
    }
}
//#endregion 🔖️Conversions

//#region 🔖️DocumentHelpers
/// 🔢️ Mints a fresh, process-unique id (`"{prefix}-{n}"`) — shared by every mutation that creates a
/// new shot/asset/saved-camera record.
pub fn next_shooting_id(prefix: &str) -> String {
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
    let next = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    format!("{prefix}-{next}")
}

/// 📄️ Parses the handcrafted DSL fixture once per call — used both for the in-plugin default document
/// and to bridge into the framework's still-JSON-only `App::example` surface, so
/// `crate::standards::v1::subsets::any::schema::snapshot::text::SHOOTING_EXAMPLE_TEXT` stays the single source of truth for the
/// snapshot.
pub fn default_snapshot() -> ShootingSnapshot {
    crate::standards::v1::subsets::any::schema::snapshot::text::parse_dsl(crate::standards::v1::subsets::any::schema::snapshot::text::SHOOTING_EXAMPLE_TEXT).unwrap_or_else(|_| crate::empty_shooting_snapshot())
}

/// 🌉️ JSON bridge for `semio_framework_plugin`'s `App::example` override, which hardcodes
/// `serde_json::from_str` on its `document_json` parameter (shared framework machinery, out of scope
/// for this migration) — derives the JSON from the DSL fixture rather than keeping a second, redundant
/// JSON copy of it on disk.
pub fn default_snapshot_json() -> String {
    json::to_json_string(&default_snapshot())
}

/// 📸️ The active shot — falls back to the first shot when `active_shot_id` names nothing (an empty
/// document, or a stale id left over after a delete).
pub fn active_shot(snapshot: &ShootingSnapshot) -> Option<&ShootingShot> {
    snapshot.shots.iter().find(|shot| shot.id == snapshot.active_shot_id).or_else(|| snapshot.shots.first())
}

/// 📦️ The active asset — same fallback rule as `active_shot`.
pub fn active_asset(snapshot: &ShootingSnapshot) -> Option<&ShootingAsset> {
    snapshot.assets.iter().find(|asset| asset.id == snapshot.active_asset_id).or_else(|| snapshot.assets.first())
}

/// 🌫️ A background of `""`/`"transparent"` means "let the surface show through" — shared by the scene
/// window's environment JSON and the icon-render request below (two consumers).
pub fn is_transparent_shooting_background(background: &str) -> bool {
    background.is_empty() || background == "transparent"
}
//#endregion 🔖️DocumentHelpers

//#region 🔖️MediaExport
/// 🌉️ Builds a real `SemioDrawingSnapshot` (canvas + one named `DrawStyle` per painted primitive
/// and a single "scene" `DrawLayer`) from the active shot/asset/scene — replaces the old hand-rolled
/// SVG string builder. The shot `shape` becomes a real `Path` (a rectangle as four `Line`
/// segments, an ellipse as two `Arc` segments — `DrawNode` has no native ellipse/rect primitive,
/// `Path` is the recursive scene graph's only drawable shape, see `shooting_shape_path_segments`);
/// the emblem override (if any) becomes a real `Image` node (base64-decoded to raw bytes — the
/// drawing subset's own svg export leaf re-encodes them, this never touches SVG text directly);
/// the active asset's name becomes a `Text` node.
///
/// Honest lossy points versus the old hand-rolled SVG (queued as `stdio_gaps`, not worked around
/// here — see ticket 26/08/11/SEMIO-ARTIFACT-UNIFIED-IMPORT-EXPORT-AND-MEDIA-FORMAT-RETIREMENT
/// w5b report): (1) `DrawNode::Text` carries no font-size/text-anchor/font-family field, so the
/// label now renders left/top-anchored at the browser's default size instead of centered/bold
/// like before; (2) `DrawCanvas.background` is captured here for round-trip fidelity but the
/// `s.stdio.semio/v1/drawing` → svg export leaf never reads it — the background is therefore
/// painted as an explicit filled `Path` layer child instead, which the export leaf DOES lower
/// into real SVG markup.
fn shooting_scene_to_semio_drawing(snapshot: &ShootingSnapshot) -> (SemioDrawingSnapshot, u32, u32) {
    let shot = active_shot(snapshot);
    let asset = active_asset(snapshot);
    let (width, height) = shot.map_or((256, 256), |entry| (entry.width, entry.height));
    let shape = shot.map_or("rectangle", |entry| entry.shape.as_str());
    let shot_background = shot.and_then(|entry| entry.background.clone()).unwrap_or_else(|| snapshot.scene.background.clone());
    let label = asset.map_or("Untitled", |entry| entry.name.as_str());

    let mut children = Vec::new();
    let mut styles = vec![DrawStyle { name: "label".into(), fill: Some(SemioRgba { r: 1.0, g: 1.0, b: 1.0, a: 1.0 }), stroke: None, stroke_width: None, opacity: None }];
    // 🖼️ The shot's `shape` is the frame every export carries, INDEPENDENT of whether that frame is
    // filled: a transparent shot still has a rectangle/ellipse outline, and the scene material's own
    // `stroke` colour is what draws it. So the shape is ALWAYS one real `Path` child (the only
    // drawable `DrawNode` — see `shooting_shape_path_segments`) and only its FILL is conditional:
    // an opaque `background` fills it, a transparent one fills it with a fully transparent colour
    // (never a missing `fill`, which SVG would render as the default opaque black).
    let canvas_background = (!is_transparent_shooting_background(&shot_background)).then(|| shooting_hex_color_to_rgba(&shot_background).unwrap_or(SemioRgba { r: 1.0, g: 1.0, b: 1.0, a: 1.0 }));
    children.push(DrawNode::Path { segments: shooting_shape_path_segments(shape, width as f64, height as f64), style: Some("shape".into()) });
    styles.insert(
        0,
        DrawStyle {
            name: "shape".into(),
            fill: Some(canvas_background.unwrap_or(SemioRgba { r: 0.0, g: 0.0, b: 0.0, a: 0.0 })),
            stroke: shooting_hex_color_to_rgba(&snapshot.scene.material.stroke),
            stroke_width: None,
            opacity: None,
        },
    );
    if let Some(bytes) = crate::shooting_emblem_bytes(snapshot).filter(|bytes| !bytes.is_empty()) {
        children.push(DrawNode::Image { at: SemioPoint2 { x: 0.0, y: 0.0 }, width: width as f64, height: height as f64, mime: "image/png".into(), bytes });
    }
    children.push(DrawNode::Text { value: label.to_string(), at: SemioPoint2 { x: width as f64 / 2.0, y: height as f64 * 0.92 }, style: Some("label".into()) });

    let drawing = SemioDrawingSnapshot {
        schema: STDIO_SEMIODRAWING_DOCUMENT_SCHEMA.into(),
        canvas: DrawCanvas { width: width as f64, height: height as f64, background: canvas_background },
        styles,
        layers: vec![DrawLayer { id: "scene".into(), name: "scene".into(), visible: true, root: DrawNode::Group { transform: SemioTransform::identity(), children } }],
    };
    (drawing, width, height)
}

/// ✏️ The shot `shape` field's only two real values, lowered to real path geometry: `"ellipse"`
/// draws a full ellipse via the standard two-`A`rc-command SVG technique (`M` to the right vertex,
/// two semicircular arcs back to the same point); anything else (`"rectangle"` in practice) draws
/// the four canvas edges as `L`ine segments.
fn shooting_shape_path_segments(shape: &str, width: f64, height: f64) -> Vec<PathSegment> {
    if shape == "ellipse" {
        let (cx, cy, rx, ry) = (width / 2.0, height / 2.0, width / 2.0, height / 2.0);
        vec![
            PathSegment::MoveTo { to: SemioPoint2 { x: cx + rx, y: cy } },
            PathSegment::ArcTo { rx, ry, x_rotation: 0.0, large_arc: true, sweep: false, to: SemioPoint2 { x: cx - rx, y: cy } },
            PathSegment::ArcTo { rx, ry, x_rotation: 0.0, large_arc: true, sweep: false, to: SemioPoint2 { x: cx + rx, y: cy } },
            PathSegment::Close,
        ]
    } else {
        vec![
            PathSegment::MoveTo { to: SemioPoint2 { x: 0.0, y: 0.0 } },
            PathSegment::LineTo { to: SemioPoint2 { x: width, y: 0.0 } },
            PathSegment::LineTo { to: SemioPoint2 { x: width, y: height } },
            PathSegment::LineTo { to: SemioPoint2 { x: 0.0, y: height } },
            PathSegment::Close,
        ]
    }
}

/// 🎨️ `"#rrggbb"`/`"#rrggbbaa"` (the only two hex shapes the shooting document ever stores in
/// `scene.background`) into a `SemioRgba`. `None` for anything else (an empty string is handled
/// by the caller's own default-color fallback before this ever runs).
fn shooting_hex_color_to_rgba(hex: &str) -> Option<SemioRgba> {
    let trimmed = hex.trim().trim_start_matches('#');
    let byte = |s: &str| u8::from_str_radix(s, 16).ok().map(|v| v as f32 / 255.0);
    match trimmed.len() {
        6 => Some(SemioRgba { r: byte(&trimmed[0..2])?, g: byte(&trimmed[2..4])?, b: byte(&trimmed[4..6])?, a: 1.0 }),
        8 => Some(SemioRgba { r: byte(&trimmed[0..2])?, g: byte(&trimmed[2..4])?, b: byte(&trimmed[4..6])?, a: byte(&trimmed[6..8])? }),
        _ => None,
    }
}

/// 🔌️ Runs the `s.stdio.semio/v1/drawing` composer registration exactly once per process —
/// idempotent (`register_composer_entries`/`register_document_codec` both overwrite on
/// re-registration, neither panics), so this is safe to call regardless of whether the hosting
/// OS/plugin runtime already ran stdio's own boot-time `plugin()` registration first.
fn shooting_ensure_semio_drawing_bridge_registered() {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(semio_s_artifact_stdio_semio::standards::v1::subsets::drawing::io::register);
}

/// 🌉️ `SemioDrawingSnapshot` → real SVG text, entirely through stdio's registered
/// `s.stdio.semio/v1/drawing` → `s.stdio.svg/1.1/*` composer entry (`io_dispatch`) — never a
/// hand-rolled SVG string. Returns the exporter's own `write_svg_xml` output (raw `<svg>…</svg>`
/// markup, no semio envelope preamble) so callers can hand it straight to
/// `rasterize_svg_to_png_base64`/embed it in an `<img>`, exactly like the old `wrap_svg` output did.
fn shooting_drawing_to_svg_text(drawing: &SemioDrawingSnapshot) -> Result<String, String> {
    shooting_ensure_semio_drawing_bridge_registered();
    let key = semio_framework_plugin::IoKey {
        artifact_kind: "s.stdio.semio".into(),
        standard: "v1".into(),
        subset: "drawing".into(),
        direction: semio_framework_plugin::IoDirection::Export,
        format_kind: "s.stdio.svg".into(),
        format_standard: "1.1".into(),
        format_subset: "*".into(),
    };
    let source = semio_framework_plugin::ErasedComposeSource {
        dialect: semio_framework_plugin::Dialect { artifact_kind: "s.stdio.semio", standard: semio_framework_plugin::StandardId("v1"), subset: semio_framework_plugin::SubsetId("drawing") },
        payload: semio_framework_plugin::IoPayload::Binary(<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(drawing)),
    };
    let composed = semio_framework_plugin::resolve_ready(semio_framework_plugin::io_dispatch(&key, std::slice::from_ref(&source))).map_err(|error| error.message)?;
    let bytes = match composed.payload {
        semio_framework_plugin::IoPayload::Binary(bytes) => bytes,
        semio_framework_plugin::IoPayload::Text(_) => return Err("s.stdio.semio/v1/drawing -> s.stdio.svg dispatch returned Text, expected Binary (ArtifactPack)".into()),
    };
    let svg_snapshot = <SvgSnapshot as store::ArtifactPack>::decode_pack(&bytes).map_err(|error| error.to_string())?;
    write_svg_xml(&svg_snapshot.doc)
}

/// 🖼️ Renders the active shot as a real SVG scene — shot shape as a filled background path, the
/// emblem override (if any) as an embedded raster image, and the asset name as a text label — via
/// the `s.stdio.semio/v1/drawing` → svg stdio bridge (`shooting_scene_to_semio_drawing` +
/// `shooting_drawing_to_svg_text`), never hand-rolled SVG string formatting.
pub fn shooting_scene_svg(snapshot: &ShootingSnapshot) -> Result<(String, u32, u32), String> {
    let (drawing, width, height) = shooting_scene_to_semio_drawing(snapshot);
    let svg = shooting_drawing_to_svg_text(&drawing)?;
    Ok((svg, width, height))
}

/// 🌉️ `shooting_scene_svg` over an already-deserialized document `Value`.
pub fn shooting_document_json_to_svg(value: &Value) -> Result<(String, u32, u32), String> {
    let dsl_value: dsl::DslValue = json::to_dsl_value(value);
    let snapshot: ShootingSnapshot = dsl::FromValue::from_value(dsl_value).map_err(|error| error.to_string())?;
    shooting_scene_svg(&snapshot)
}

/// 🖼️ Builds the icon-render host request JSON for `shot`/`asset` under `fixture`'s scene lighting —
/// consumed both by the icon window's `render()` and by the `exportActiveShot`/`exportAllShots` shell
/// commands (`🎮️commands/🖨️export`), two consumers. `fit` mirrors the scene window's centre-model
/// lane (`ShootingConfig::center_model`): the host re-targets the shot camera at the asset's bounding
/// sphere and backs off to frame it, so the icon shows what the centred scene shows.
pub fn shooting_icon_render_request_json(snapshot: &ShootingSnapshot, shot: &ShootingShot, asset: &ShootingAsset, fallback_camera: &ShootingCamera, fit: bool) -> String {
    let vec3 = |v: [f64; 3]| Value::from(v.iter().map(|c| Value::from(*c)).collect::<Vec<Value>>());
    let camera = crate::shooting_resolve_shot_camera(snapshot, shot, fallback_camera);
    let scene = &snapshot.scene;
    let mut camera_value = json!({
        "position": vec3(camera.position),
        "target": vec3(camera.target),
        "zoom": camera.zoom,
        "fov": camera.fov,
        "projection": camera.projection.clone().unwrap_or_else(|| "perspective".into()),
    });
    if let (Some(object), Some(up)) = (camera_value.as_object_mut(), camera.up) {
        object.insert("up", vec3(up));
    }
    let mut value = json!({
        "assetUrl": asset.url.as_str(),
        "camera": camera_value,
        "fit": { "enabled": fit, "padding": 1.25 },
        "lights": {
            "ambientIntensity": scene.ambient.intensity,
            "ambientColor": scene.ambient.color.as_str(),
            "sunAzimuth": scene.sun.azimuth,
            "sunElevation": scene.sun.elevation,
            "sunIntensity": scene.sun.intensity,
            "sunColor": scene.sun.color.as_str(),
        },
        "width": shot.width,
        "height": shot.height,
        "format": shot.format.as_str(),
        "shape": if shot.shape == "ellipse" { "ellipse" } else { "rectangle" },
        "shadowEnabled": scene.shadow.enabled,
        "material": {
            "color": scene.material.color.as_str(),
            "metalness": scene.material.metalness,
            "roughness": scene.material.roughness,
            "emissive": scene.material.emissive.as_str(),
            "emissiveIntensity": scene.material.emissive_intensity,
            "stroke": scene.material.stroke.as_str(),
        },
    });
    if let Some(object) = value.as_object_mut() {
        let background = shot.background.clone().unwrap_or_else(|| scene.background.clone());
        if !is_transparent_shooting_background(&background) {
            object.insert("background", json!(background.as_str()));
        }
    }
    value.to_string()
}
