//! 🧱️ generation3d → `s.stdio.ply@1.0` — the document's EVALUATED preview mesh as real ASCII PLY.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf emitted the artifact's own DSL text
//! under a `.ply` name (see the stl sibling's doc comment for the shared defect).
//!
//! Composition: caller-prepared `SemioMeshSnapshot` → `SemioMeshToPly` → ply's own `encode_ply`.
//! PLY is the one mesh target here that also accepts a `Points` primitive, so a wire/point preview
//! exports as a real, valid PLY point cloud with no `face` element rather than erroring.
use crate::standards::v1::subsets::any::io::mesh_bridge::io_error;
use semio_framework_plugin::ArtifactSerializer;
use semio_s_artifact_stdio_ply::PlySnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::ply::v1_0::any::SemioMeshToPly;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;

pub fn serialize_mesh(mesh: &SemioMeshSnapshot) -> Result<PlySnapshot, semio_framework_diagnostic::TextError> {
    semio_framework_plugin::resolve_ready(SemioMeshToPly::serialize(mesh)).map_err(|error| io_error(format!("generation3d→ply: {error}")))
}

pub fn serialize_mesh_bytes(mesh: &SemioMeshSnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    semio_s_artifact_stdio_ply::engine::encode_ply(&serialize_mesh(mesh)?).map_err(|error| io_error(format!("generation3d→ply: {error}")))
}

//! 🖊️ generation3d → `s.stdio.dwg` — the document's EVALUATED preview mesh as a real DWG polyface mesh.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf emitted the artifact's own DSL text
//! under a `.dwg` name (see the stl sibling's doc comment for the shared defect).
//!
//! Composition: caller-prepared `SemioMeshSnapshot` → `SemioMeshToDwg`, which builds one real
//! `DwgGeometry::PolyfaceMesh` entity on its own layer — a mesh entity, not an edge-polyline
//! fallback — then dwg's own `encode_dwg` for the native container bytes.
//!
//! 🔖 Standard note: this artifact's registered export dialect is `ac1018` (R2004) and the writer
//! `encode_dwg` reaches is the R2004 canonical writer, so the label and the bytes agree; the
//! `SemioMeshToDwg` bridge lives under the dwg artifact's `ac1024` module tree only because that is
//! where the shared logical drawing model was rehomed — one `DwgSnapshot` type serves both.
use crate::standards::v1::subsets::any::io::mesh_bridge::io_error;
use semio_framework_plugin::ArtifactSerializer;
use semio_s_artifact_stdio_dwg::DwgSnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::dwg::v_ac1024::any::SemioMeshToDwg;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;

pub fn serialize_mesh(mesh: &SemioMeshSnapshot) -> Result<DwgSnapshot, semio_framework_diagnostic::TextError> {
    semio_framework_plugin::resolve_ready(SemioMeshToDwg::serialize(mesh)).map_err(|error| io_error(format!("generation3d→dwg: {error}")))
}

/// 🖊️ Native container bytes, through dwg's own `AC1015` writer — the exact one `encode_dwg`
/// dispatches to for this version.
///
/// 🐛️ `encode_dwg` itself is NOT the entry point here, and the reason is a real, reproduced
/// incompatibility between two stdio components rather than a preference: after writing, it
/// cross-checks the produced file header's maintenance byte and codepage word against the
/// `DwgSnapshot`'s own `maintenance_version`/`codepage` fields, and `SemioMeshToDwg` builds its
/// snapshot with `..DwgSnapshot::default()` — leaving both at `0` while the `AC1015` writer stamps
/// a real codepage. The result was `DWG header mismatch: codepage 36865 != 0` on every export.
/// Stamping those fields here would mean this leaf hard-coding another artifact's writer constants;
/// calling the writer directly keeps one source of truth for them, and `decode_dwg` reads the
/// triple back out of the bytes anyway (it never consults the snapshot), so the round trip is
/// unaffected.
pub fn serialize_mesh_bytes(mesh: &SemioMeshSnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    let drawing = serialize_mesh(mesh)?.drawing.to_native().map_err(|error| io_error(format!("generation3d→dwg: {error}")))?;
    semio_s_artifact_stdio_dwg::engine::dwg_to_bytes(&drawing).map_err(|error| io_error(format!("generation3d→dwg: {error}")))
}

//! 🔺️ generation3d → `s.stdio.stl@ascii` — the document's EVALUATED preview mesh as real ASCII STL.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf returned
//! `print_dsl(snapshot).into_bytes()` — the artifact's own native DSL TEXT, mislabelled `.stl`. It
//! never emitted a single facet and never failed, so "Export to STL" looked like it worked.
//!
//! The real conversion is a two-step composition of code that already exists and is already tested:
//! caller-prepared `SemioMeshSnapshot` accepts the supplied materialized
//! `s.stdio.semio@v1/mesh` document, and `SemioMeshToStl` (that subset's own bridge, with its own
//! unit tests) turns it into a `StlSnapshot`. Bytes come from stl's own `encode_stl_ascii` grammar —
//! deliberately NOT `ArtifactDsl::print_dsl`, which wraps the facets in a `semio` envelope preamble
//! that no STL reader accepts.
//!
//! 🔖 Documented lossiness is `SemioMeshToStl`'s own: STL is triangles-only and non-indexed, so a
//! preview that carries no face connectivity (a wire or point preview) is a typed error rather than
//! invented geometry, and per-vertex normals collapse to one facet normal.
use crate::standards::v1::subsets::any::io::mesh_bridge::io_error;
use semio_framework_plugin::ArtifactSerializer;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::stl::v_ascii::any::SemioMeshToStl;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;
use semio_s_artifact_stdio_stl::StlSnapshot;

/// 🔺️ The mesh half, isolated so the round-trip test can drive it without a live flow evaluator.
pub fn serialize_mesh(mesh: &SemioMeshSnapshot) -> Result<StlSnapshot, semio_framework_diagnostic::TextError> {
    semio_framework_plugin::resolve_ready(SemioMeshToStl::serialize(mesh)).map_err(|error| io_error(format!("generation3d→stl: {error}")))
}

pub fn serialize_mesh_bytes(mesh: &SemioMeshSnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    Ok(semio_s_artifact_stdio_stl::engine::encode_stl_ascii(&serialize_mesh(mesh)?).into_bytes())
}

//! 🚪️ IO s.generation3d (1/✳️any) — registration now flows through 🎹️composer::register
//! (called once from ⚙️engine::register), not per-leaf register().
pub fn import_stdio_kinds() -> &'static [&'static str] {
    &["stdio.dwg", "stdio.gltf", "stdio.json", "stdio.obj", "stdio.ply", "stdio.stl", "stdio.txt"]
}
// 🖼️ No "stdio.png"/"stdio.json" here (export-only list): generation2d owns those EXPORT claims, see
// `🚪️IoRegistry` region below. Import is unaffected — both stay in `import_stdio_kinds` above.
pub fn export_stdio_kinds() -> &'static [&'static str] {
    &["stdio.dwg", "stdio.gltf", "stdio.las", "stdio.obj", "stdio.ply", "stdio.stl", "stdio.txt"]
}
//#region 🔺️MeshBridge
/// 🔺️ Converts caller-prepared geometry and editable graph documents through the owning codecs.
/// Geometry evaluation and retention belong to the calling composition.
pub mod mesh_bridge {
    use crate::Generation3dSnapshot;
    use semio_framework_artifact_flow_flow::neural::Dictionary;
    use semio_framework_artifact_flow_flow::{CameraJson, FlowHostSnapshot, OrderedMap, OrderedSet, SynapseSpec, Widget, WidgetLayout};
    use semio_framework_plugin::MeshData;
    use semio_s_artifact_stdio_semio::standards::v1::subsets::base::schema::geometry::SemioPoint3;
    use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::{SemioMesh, SemioMeshSnapshot, SemioPrimitive, SemioTopology, STDIO_SEMIOMESH_DOCUMENT_SCHEMA};

    /// 🏷️ Widget ids the import fixture plants, stable so a re-import overwrites rather than stacks.
    pub const IMPORT_SOURCE_WIDGET: &str = "imported-source";
    pub const IMPORT_GEOMETRY_WIDGET: &str = "imported-geometry";
    pub const IMPORT_PREVIEW_WIDGET: &str = "imported-preview";
    /// 🏷️ `SemioMesh` id every export carries — the merged preview, not a per-widget mesh.
    pub const EXPORT_MESH_ID: &str = "generation3d-preview";

    /// 🚨️ Every failure in this artifact's IO is a typed error carrying WHY — an empty document is
    /// never a legal answer to bytes that did not decode.
    pub fn io_error(message: impl Into<String>) -> semio_framework_diagnostic::TextError {
        semio_framework_diagnostic::TextError::new(message.into(), semio_framework_diagnostic::TextSpan::at(1, 1))
    }

    /// 🔤️ Standard base64 (RFC 4648 §4, `=`-padded) — the exact spelling the brep extension's own
    /// `decode_base64` accepts on a `brep.io.import*` node's `data` channel. Reused from the gltf
    /// artifact's data-uri codec rather than re-derived here.
    pub fn base64_encode(bytes: &[u8]) -> String {
        semio_s_artifact_stdio_gltf::engine::b64_encode(bytes)
    }

    /// 🔤️ Inverse of [`base64_encode`], for reading an import fixture's planted payload back.
    pub fn base64_decode(text: &str) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
        semio_s_artifact_stdio_gltf::engine::b64_decode(text).map_err(io_error)
    }

    /// 🔺️ Neutral materialized geometry as this repo's own typed mesh document.
    ///
    /// `MeshData` is the tessellation wire form: flat `f32` triples plus a `u32` index buffer. A
    /// mesh WITHOUT indices carries no face connectivity at all (a wire/point preview), so it
    /// becomes a `Points` primitive rather than being silently reinterpreted as a triangle soup —
    /// the format bridges that cannot represent points then refuse it by name instead of writing
    /// invented triangles.
    pub fn semio_mesh_from_mesh_data(mesh: &MeshData) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
        if mesh.positions.len() < 3 {
            return Err(io_error("generation3d export: prepared geometry has no positions"));
        }
        if mesh.positions.len() % 3 != 0 {
            return Err(io_error(format!("generation3d export: prepared mesh has {} position floats, not a multiple of 3", mesh.positions.len())));
        }
        if mesh.positions.iter().any(|value| !value.is_finite()) {
            return Err(io_error("generation3d geometry contains non-finite positions"));
        }
        let positions: Vec<SemioPoint3> = mesh.positions.chunks_exact(3).map(|p| SemioPoint3 { x: p[0] as f64, y: p[1] as f64, z: p[2] as f64 }).collect();
        let normals: Vec<SemioPoint3> =
            if mesh.normals.len() == mesh.positions.len() { mesh.normals.chunks_exact(3).map(|n| SemioPoint3 { x: n[0] as f64, y: n[1] as f64, z: n[2] as f64 }).collect() } else { Vec::new() };
        let topology = if mesh.indices.is_empty() { SemioTopology::Points } else { SemioTopology::Triangles };
        if topology == SemioTopology::Triangles && mesh.indices.len() % 3 != 0 {
            return Err(io_error(format!("generation3d export: prepared mesh has {} indices, not a multiple of 3", mesh.indices.len())));
        }
        if let Some(out_of_range) = mesh.indices.iter().find(|index| **index as usize >= positions.len()) {
            return Err(io_error(format!("generation3d export: prepared mesh index {out_of_range} is out of range for {} vertices", positions.len())));
        }
        let primitive = SemioPrimitive { id: format!("{EXPORT_MESH_ID}-prim-0"), topology, positions, normals, uvs: Vec::new(), colors: Vec::new(), indices: mesh.indices.clone(), material_id: None };
        Ok(SemioMeshSnapshot { schema: STDIO_SEMIOMESH_DOCUMENT_SCHEMA.into(), meshes: vec![SemioMesh { id: EXPORT_MESH_ID.into(), primitives: vec![primitive] }], materials: Vec::new(), textures: Vec::new() })
    }

    /// 🧩️ Merges prepared meshes while preserving each indexed geometry's vertex offset.
    pub fn merge_meshes(meshes: &[semio_framework_plugin::MeshData]) -> semio_framework_plugin::MeshData {
        let mut merged = semio_framework_plugin::MeshData::default();
        for mesh in meshes {
            let vertex_offset = (merged.positions.len() / 3) as u32;
            merged.positions.extend(&mesh.positions);
            merged.normals.extend(&mesh.normals);
            merged.colors.extend(&mesh.colors);
            merged.indices.extend(mesh.indices.iter().map(|index| index + vertex_offset));
            merged.edge_positions.extend(&mesh.edge_positions);
            if !mesh.edge_ids.is_empty() {
                let edge_base = merged.edge_ids.len() as u32;
                merged.edge_ids.extend(mesh.edge_ids.iter().map(|id| id + edge_base));
            }
        }
        merged
    }

    /// 📥️ Converts validated geometry into this artifact's editable graph document.
    pub fn generation3d_document_from_mesh(mesh: &MeshData) -> Result<semio_framework_pack_json::Value, String> {
        let snapshot = import_mesh_data(mesh).map_err(|error| error.to_string())?;
        let value = semio_framework_pack_json::from_dsl_value(&protocol::ToValue::to_value(&snapshot));
        snapshot.retire_cold();
        Ok(value)
    }

    /// 📤️ Validates the declared document and geometry prepared by its retained evaluation owner.
    pub fn generation3d_mesh_from_document(doc: &dsl::DslValue, prepared: &MeshData) -> Result<MeshData, String> {
        let snapshot = <Generation3dSnapshot as protocol::FromValue>::from_value(doc.clone()).map_err(|error| error.to_string())?;
        snapshot.retire_cold();
        semio_mesh_from_mesh_data(prepared).map_err(|error| error.to_string())?;
        Ok(prepared.clone())
    }

    /// 📦️ Encodes the supplied mesh through the canonical STL grammar.
    pub fn stl_ascii_bytes(mesh: &SemioMeshSnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
        let stl = semio_framework_plugin::resolve_ready(<semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::stl::v_ascii::any::SemioMeshToStl as semio_framework_plugin::ArtifactSerializer>::serialize(mesh))
            .map_err(|error| io_error(error.to_string()))?;
        Ok(semio_s_artifact_stdio_stl::engine::encode_stl_ascii(&stl).into_bytes())
    }

    /// 📥️ The three-widget import fixture: a note holding the payload, a `brep.io.import*` neuron
    /// that turns it into real BRep geometry, and a preview sink. `preview: true` on the neuron is
    /// what puts the imported mesh in the 3D window (`widget_previews`).
    pub fn import_document(neuron_kind: &str, data_text: String) -> Generation3dSnapshot {
        import_graph(neuron_kind, data_text, "geometry")
    }

    /// 🥽️ Preserves an indexed triangle mesh as editable polygon data in the procedural graph.
    pub fn import_mesh_data(mesh: &MeshData) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
        if mesh.positions.len() < 9 || mesh.positions.len() > 300_000 || mesh.positions.len() % 3 != 0 || mesh.positions.iter().any(|value| !value.is_finite()) {
            return Err(io_error("mesh import requires 3..100000 finite three-dimensional vertices"));
        }
        if mesh.indices.is_empty() || mesh.indices.len() > 300_000 || mesh.indices.len() % 3 != 0 {
            return Err(io_error("mesh import requires 1..100000 indexed triangles"));
        }
        if mesh.indices.iter().any(|id| *id as usize >= mesh.positions.len() / 3) || mesh.indices.chunks_exact(3).any(|triangle| triangle[0] == triangle[1] || triangle[1] == triangle[2] || triangle[0] == triangle[2]) {
            return Err(io_error("mesh import contains an invalid triangle index"));
        }
        let vertices = semio_framework_pack_json::array(mesh.positions.chunks_exact(3).map(|point| semio_framework_pack_json::array(point.iter().map(|coordinate| semio_framework_pack_json::Value::from(*coordinate as f64)))));
        let faces = semio_framework_pack_json::array(mesh.indices.chunks_exact(3).map(|triangle| semio_framework_pack_json::array(triangle.iter().map(|id| semio_framework_pack_json::Value::from(*id)))));
        let data = semio_framework_pack_json::object([("vertices".into(), vertices), ("faces".into(), faces)]).to_string();
        if data.len() > 16_000_000 { return Err(io_error("mesh input exceeds 16 MB")); }
        Ok(import_graph("brep.mesh.construct", data, "meshOut"))
    }

    fn import_graph(neuron_kind: &str, data_text: String, output_port: &str) -> Generation3dSnapshot {
        let mut layout = OrderedMap::new();
        layout.insert(IMPORT_SOURCE_WIDGET.to_string(), WidgetLayout { x: 0.0, y: 0.0 });
        layout.insert(IMPORT_GEOMETRY_WIDGET.to_string(), WidgetLayout { x: 260.0, y: 0.0 });
        layout.insert(IMPORT_PREVIEW_WIDGET.to_string(), WidgetLayout { x: 520.0, y: 0.0 });
        let fixture = FlowHostSnapshot {
            schema: "flow.host_snapshot".into(),
            camera: CameraJson { x: 0.0, y: 0.0, zoom: 1.0 },
            widgets: vec![
                Widget::InputNote { id: IMPORT_SOURCE_WIDGET.into(), text: data_text },
                Widget::Neuron { id: IMPORT_GEOMETRY_WIDGET.into(), neuron_kind: neuron_kind.into(), params: Dictionary::new(), input_ports: Vec::new(), output_ports: Vec::new(), preview: true },
                Widget::OutputPreview { id: IMPORT_PREVIEW_WIDGET.into(), preview: Dictionary::new(), expanded: OrderedSet::new() },
            ],
            synapses: vec![
                SynapseSpec { id: "imported-data".into(), from: IMPORT_SOURCE_WIDGET.into(), to: IMPORT_GEOMETRY_WIDGET.into(), from_port: "text".into(), to_port: "data".into() },
                SynapseSpec { id: "imported-geometry".into(), from: IMPORT_GEOMETRY_WIDGET.into(), to: IMPORT_PREVIEW_WIDGET.into(), from_port: output_port.into(), to_port: String::new() },
            ],
            layout,
        };
        Generation3dSnapshot { host_snapshot: fixture, ..Generation3dSnapshot::default() }
    }

    /// 🔎️ The payload an import fixture planted, and the neuron kind that consumes it.
    pub fn imported_source(snapshot: &Generation3dSnapshot) -> Option<(&str, &str)> {
        let text = snapshot.host_snapshot.widgets.iter().find_map(|widget| match widget {
            Widget::InputNote { id, text } if id == IMPORT_SOURCE_WIDGET => Some(text.as_str()),
            _ => None,
        })?;
        let kind = snapshot.host_snapshot.widgets.iter().find_map(|widget| match widget {
            Widget::Neuron { id, neuron_kind, .. } if id == IMPORT_GEOMETRY_WIDGET => Some(neuron_kind.as_str()),
            _ => None,
        })?;
        Some((kind, text))
    }
}
