//! 🗂️ S Home launcher app command — `delete-virtual-file-system-node`: retires one local-only studio from Home.
//!
//! Event-sourced, never a CRUD delete: the command emits exactly one config event,
//! [`HomeConfigMutation::RetireLocalStudio`] — a tombstone in the Home config ledger — and performs no catalog IO. The
//! studio's catalog document and its whole history stay intact; Home simply stops listing it, and the event's exact
//! inverse ([`HomeConfigMutation::RestoreLocalStudio`]) lists it again in this session. A persisted studio is also unlisted
//! from the host's local document catalog (`os.local-catalog.retire`: its files stay on disk), so a reload does not hand it
//! back; undoing the removal lists it again only until the next reload. Hub spaces are never addressed here: the hub
//! directory owns their deletion (`deleteSpace` → `os.directory.delete-space`).

use crate::editor::home::config::{local_studio_id_is_admissible, HomeConfig, HomeConfigMutation};
use crate::standards::v1::subsets::any::schema::mutations::text::SHomeMutation;
use crate::SHomeSnapshot;
use semio_framework_plugin::{ArtifactView, ConfigView, Effect, Emit, Fault, FaultOrigin};

#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::DslRecord)]
#[dsl(keyword = "delete-vfs-node")]
pub struct DeleteVirtualFileSystemNode {
    pub node_id: String,
}

/// 🪪️ The local studio id one Home file-tree node names: `studio:<id>`, or the bare id.
pub fn local_studio_id(node_id: &str) -> &str {
    node_id.strip_prefix("studio:").unwrap_or(node_id)
}

/// 🚫️ The direct lane cannot tell a hub space from a local studio: removal runs only as the retained job.
pub fn handle(_payload: &DeleteVirtualFileSystemNode, _doc: &ArtifactView<'_, SHomeSnapshot>, _cfg: &ConfigView<'_, HomeConfig>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    Err(Fault::new(FaultOrigin::App, "s.home.delete-vfs-node.requires-retained-job", "removing a Home node runs only as the retained job"))
}

/// 🪦️ The retained route: `hub_row` is the id's one folded directory row from the job's captured projection — a listed
/// hub space is refused, because the hub directory owns its deletion.
pub fn handle_with_row(payload: &DeleteVirtualFileSystemNode, _doc: &ArtifactView<'_, SHomeSnapshot>, cfg: &ConfigView<'_, HomeConfig>, hub_row: Option<&store::os_directory::DirectorySpace>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    let space_id = local_studio_id(&payload.node_id);
    if !local_studio_id_is_admissible(space_id) {
        return Err(Fault::new(FaultOrigin::App, "s.home.delete-vfs-node.node-invalid", "the node id names no admissible local studio"));
    }
    if hub_row.is_some() {
        return Err(Fault::new(FaultOrigin::App, "s.home.delete-vfs-node.hub-space", format!("{space_id} is a hub space; the hub directory deletes it (Delete Space)")));
    }
    if cfg.snapshot.is_local_studio_retired(space_id) {
        return Err(Fault::new(FaultOrigin::App, "s.home.delete-vfs-node.already-retired", format!("local studio {space_id} is already retired from Home")));
    }
    let Some(entry) = semio_framework_plugin::resolve_ready(crate::list_all_space_catalog_entries()).into_iter().find(|entry| entry.id == space_id) else {
        return Err(Fault::new(FaultOrigin::App, "s.home.delete-vfs-node.unknown-local-studio", format!("no local studio {space_id} is listed in Home")));
    };
    let unkeep = (!entry.backbone_uri.is_empty()).then(|| Effect::ReplayShellCommand { action_id: "os.local-catalog.retire".into(), args: Some(semio_framework_pack_json::to_dsl_value(&semio_framework_pack_json::json!({ "documentId": space_id }))) });
    Ok(Emit { config_mutations: vec![HomeConfigMutation::RetireLocalStudio { space_id: space_id.to_owned() }], effects: unkeep.into_iter().collect(), ..Default::default() })
}

//! 📎️ S Home launcher app command — `bind-space-file`: binds a local studio to a file on disk.
//!
//! IO-owning retained work in two stages (`HomeCatalogWork`, editor): [`validate`] resolves the studio and the path
//! without writing anything, [`commit`] opens the file backbone, writes the studio's event-sourced document into it,
//! admits the file-backed studio into the local catalog (so Home keeps listing it once its ephemeral draft is gone) and
//! publishes `change-catalog-generation`. The job checkpoints between the stages, so a
//! cancellation before [`commit`] writes nothing, and every refusal is named (`s.home.bind-space-file.*`). On a guest
//! without a filesystem (every `wasm32` shell) the commit asks the host's local document catalog to bind the studio instead
//! (`os.local-catalog.admit`, storage `file`) and the host hands the kept studio back.
//! @see ✏️s/🔌️plugins/🪐️space/🗿️artifacts/🏠️home/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs `HomeCatalogWork`

use crate::editor::home::config::{local_studio_id_is_admissible, HomeConfig, HomeConfigMutation};
use crate::standards::v1::subsets::any::schema::mutations::text::SHomeMutation;
use crate::SHomeSnapshot;
use semio_framework_plugin::{ArtifactView, ConfigView, Emit, Fault, FaultOrigin};

#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::DslRecord)]
#[dsl(keyword = "bind-space-file")]
pub struct BindSpaceFile {
    pub space_id: String,
    pub file_path: String,
}

pub fn handle(_payload: &BindSpaceFile, _doc: &ArtifactView<'_, SHomeSnapshot>, _cfg: &ConfigView<'_, HomeConfig>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    Err(Fault::new(FaultOrigin::App, "s.home.bind-space-file.requires-retained-job", "binding a studio file writes the filesystem and the local catalog and runs only as the retained bind job"))
}

/// 🔎️ Stage one — the studio must exist and the path must name a file on a host with a filesystem; writes nothing.
pub fn validate(payload: &BindSpaceFile) -> Result<(), Fault> {
    if !local_studio_id_is_admissible(&payload.space_id) {
        return Err(Fault::new(FaultOrigin::App, "s.home.bind-space-file.studio-invalid", "the studio id is empty, oversized or carries control characters"));
    }
    if payload.file_path.trim().is_empty() || payload.file_path.chars().any(char::is_control) {
        return Err(Fault::new(FaultOrigin::App, "s.home.bind-space-file.path-invalid", "the file path is empty or carries control characters"));
    }
    semio_framework_plugin::resolve_ready(crate::resolve_studio_document(&payload.space_id))
        .map(|_| ())
        .ok_or_else(|| Fault::new(FaultOrigin::App, "s.home.bind-space-file.unknown-studio", format!("no local studio {} exists", payload.space_id)))
}

/// 💾️ Stage two — the one filesystem + catalog write, then the catalog generation bump.
#[cfg(not(target_arch = "wasm32"))]
pub fn commit(payload: &BindSpaceFile, doc: &ArtifactView<'_, SHomeSnapshot>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    use semio_framework_os::{document_backbone_ref, encode_backbone_payload, OsBackbonePort as _};
    let refused = |error: semio_framework_os::VcsError| Fault::new(FaultOrigin::App, "s.home.bind-space-file.io-failed", format!("binding {} to {} failed: {error:?}", payload.space_id, payload.file_path));
    let uri = format!("file://{}", payload.file_path);
    let port = semio_framework_os::open_file_space_backbone(&payload.file_path).map_err(refused)?;
    let mut document = semio_framework_plugin::resolve_ready(crate::resolve_studio_document(&payload.space_id)).ok_or_else(|| Fault::new(FaultOrigin::App, "s.home.bind-space-file.unknown-studio", format!("no local studio {} exists", payload.space_id)))?;
    document.backbone = Some(semio_framework_plugin::resolve_ready(document_backbone_ref(&uri)));
    port.write(&uri, &encode_backbone_payload(&document).map_err(refused)?).map_err(refused)?;
    semio_framework_plugin::resolve_ready(crate::register_studio_port(&payload.space_id, port));
    semio_framework_os::host::admit_os_space_document(document, &semio_framework_plugin::resolve_ready(crate::catalog_port())).map_err(refused)?;
    let draft_port = semio_framework_plugin::resolve_ready(crate::draft_backbone_port());
    semio_framework_plugin::resolve_ready(crate::ephemeral_draft_catalog()).discard_draft(&draft_port, &payload.space_id);
    Ok(Emit::mutations(vec![crate::standards::v1::subsets::any::schema::mutations::change_catalog_generation(doc.snapshot.catalog_generation + 1)]))
}

/// 📮️ Stage two on a guest without a filesystem — the host binds the studio to the file: one `os.local-catalog.admit`
/// request with the studio's own pack/spr pair; the host writes it, records it in its local catalog and hands it back
/// through `applyLocalCatalogDocument`, which lists it as persisted.
#[cfg(target_arch = "wasm32")]
pub fn commit(payload: &BindSpaceFile, _doc: &ArtifactView<'_, SHomeSnapshot>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    Ok(Emit::effect(super::apply_local_catalog_document::keep_on_device(&payload.space_id, "file", &payload.file_path)?))
}

//! 🗃️ S Home launcher app command — `apply-local-catalog-document`: the host hands back one studio it keeps on this device.
//!
//! A guest has no filesystem, so the studios this device keeps (persisted into a folder, bound to a file, or imported) live
//! in the host's local document catalog (`os.config.local-catalog`, persisted local-only) and in their own folder lane. On
//! every Home mount the host re-hydrates the guest with each kept studio's own pack/spr pair through this chrome-audience
//! view action. It is IO-owning retained work in two stages (`HomeCatalogWork`, editor): [`validate`] decodes the pair and
//! checks it is the named studio's event-sourced document, writing nothing; [`commit`] admits it into the local catalog
//! under its own id and manifest name (idempotent: a repeated page re-lists nothing twice) and publishes
//! `change-catalog-generation`. It never asks the host to keep the studio again — only the user's own persist, bind and
//! import commits do — so a re-hydration can never loop back into an admission. The admitted studio replaces the ephemeral
//! draft of the same id, if one is still listed: the host now keeps it.
//!
//! [`keep_on_device`] is the guest half of the lane: the request a persist, bind or import commit hands the host.
//! @see ✏️s/🔌️plugins/🪐️space/🗿️artifacts/🏠️home/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs `HomeCatalogWork`
//! @see 🧰️framework/🛍️products/💻️os/🔨️modules/📺️renderer/🧑‍🎨engine/🧱️elements/🏛️ShellHost/🗂️local-catalog/🟦️.ts

use crate::editor::home::config::{local_studio_id_is_admissible, HomeConfig, HomeConfigMutation};
use crate::standards::v1::subsets::any::schema::mutations::change_catalog_generation;
use crate::standards::v1::subsets::any::schema::mutations::text::SHomeMutation;
use crate::SHomeSnapshot;
use semio_framework_plugin::{ArtifactView, ConfigView, Effect, Emit, Fault, FaultOrigin};

#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::DslRecord)]
#[dsl(keyword = "apply-local-catalog-document")]
pub struct ApplyLocalCatalogDocument {
    pub document_id: String,
    pub pack: String,
    pub spr: String,
}

pub fn handle(_payload: &ApplyLocalCatalogDocument, _doc: &ArtifactView<'_, SHomeSnapshot>, _cfg: &ConfigView<'_, HomeConfig>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    Err(Fault::new(FaultOrigin::App, "s.home.apply-local-catalog-document.requires-retained-job", "re-hydrating a kept studio writes the local catalog and runs only as the retained catalog job"))
}

fn decoded(payload: &ApplyLocalCatalogDocument) -> Result<(Vec<u8>, Vec<u8>), Fault> {
    let invalid = |part: &str| Fault::new(FaultOrigin::App, "s.home.apply-local-catalog-document.encoding-invalid", format!("the kept studio's {part} is not base64"));
    Ok((protocol::base64_standard_decode(&payload.pack).map_err(|_| invalid("pack"))?, protocol::base64_standard_decode(&payload.spr).map_err(|_| invalid("spr"))?))
}

/// 🔎️ Stage one — the pair must decode into the named studio's space document; writes nothing.
pub fn validate(payload: &ApplyLocalCatalogDocument) -> Result<(), Fault> {
    if !local_studio_id_is_admissible(&payload.document_id) {
        return Err(Fault::new(FaultOrigin::App, "s.home.apply-local-catalog-document.id-invalid", "the kept studio's id is empty, oversized or carries control characters"));
    }
    let (pack, spr) = decoded(payload)?;
    let parsed: store::ParsedDocumentText<semio_framework_artifact_space_space::SpaceSnapshot, semio_framework_artifact_space_space::SpaceMutation> = semio_framework_plugin::resolve_ready(store::parse_document_pack(&pack, &spr))
        .map_err(|error| Fault::new(FaultOrigin::App, "s.home.apply-local-catalog-document.not-a-studio", format!("the kept studio's pair is not a studio document: {error}")))?;
    let envelope = parsed.into_envelope();
    let named = envelope.schema == semio_framework_artifact_space_space::S_SPACE_SCHEMA && envelope.id == payload.document_id;
    envelope.retire_unadopted();
    if !named {
        return Err(Fault::new(FaultOrigin::App, "s.home.apply-local-catalog-document.mismatch", format!("the kept pair is not the studio document {}", payload.document_id)));
    }
    Ok(())
}

/// 💾️ Stage two — the one catalog write: admits the kept studio under its own id and name, then bumps the catalog generation.
pub fn commit(payload: &ApplyLocalCatalogDocument, doc: &ArtifactView<'_, SHomeSnapshot>) -> Result<Emit<SHomeMutation, HomeConfigMutation>, Fault> {
    let (pack, spr) = decoded(payload)?;
    semio_framework_os::host::import_os_space_from_pack(&pack, &spr, &semio_framework_plugin::resolve_ready(crate::catalog_port()))
        .map_err(|error| Fault::new(FaultOrigin::App, "s.home.apply-local-catalog-document.catalog-refused", format!("the local catalog refused the kept studio: {error:?}")))?;
    let draft_port = semio_framework_plugin::resolve_ready(crate::draft_backbone_port());
    semio_framework_plugin::resolve_ready(crate::ephemeral_draft_catalog()).discard_draft(&draft_port, &payload.document_id);
    Ok(Emit::mutations(vec![change_catalog_generation(doc.snapshot.catalog_generation + 1)]))
}

/// 📮️ Asks the host to keep one local studio on this device (`os.local-catalog.admit`) with the studio's own event-sourced
/// pack/spr pair: `storage` is `folder` or `file`, an empty `target` means the device's own data folder. The host writes the
/// studio into that lane, records it in its local catalog and hands it back through `applyLocalCatalogDocument`.
pub fn keep_on_device(space_id: &str, storage: &str, target: &str) -> Result<Effect, Fault> {
    let refused = |code: &'static str, message: String| Fault::new(FaultOrigin::App, code, message);
    let document = semio_framework_plugin::resolve_ready(crate::resolve_studio_document(space_id)).ok_or_else(|| refused("s.home.keep-on-device.unknown-studio", format!("no local studio {space_id} exists")))?;
    let files = semio_framework_os::export_backbone_pack(&document).map_err(|error| refused("s.home.keep-on-device.export-failed", format!("studio {space_id} could not be exported: {error:?}")))?;
    let name = semio_framework_os::materialize_backbone_snapshot(&document, &[]).map_err(|error| refused("s.home.keep-on-device.export-failed", format!("studio {space_id} could not be read: {error:?}")))?.name;
    let args = semio_framework_pack_json::to_dsl_value(&semio_framework_pack_json::json!({
        "documentId": space_id,
        "schema": semio_framework_artifact_space_space::S_SPACE_SCHEMA,
        "name": name.trim(),
        "storage": storage,
        "target": target.trim(),
        "pack": protocol::base64_standard_encode(&files.pack),
        "spr": protocol::base64_standard_encode(&files.spr),
    }));
    Ok(Effect::ReplayShellCommand { action_id: "os.local-catalog.admit".into(), args: Some(args) })
}

