        })
        .window_kind_interactions(PLAYBOOK_PLAY_WINDOW_BUILDER, vec![InteractionRef::new(PLAYBOOK_INTERACTION_BLOCKS)])
        // 🎯️ Typed channel surface (mirrors `writer_ui::create_writer_app`'s identical wiring) —
