//! 📐️ Fixture geometry import — builds kernel handles from authored spatial.model geometry.
//!
//! 🧱️ Ticket `26/08/12/UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM` wave 3: `CadGeometry`/`CadObject` and
//! their topology substructs used to be PUBLIC, PERSISTED fields on `CadSnapshot` — a hand-rolled
//! B-Rep model duplicating `SemioBrepSnapshot`'s canonical topology (four independent B-Rep models
//! existed in the repo before this wave). They are now PRIVATE to this module, an EPHEMERAL
//! authoring/import intermediate — parsed fresh from `spatial.model`-shaped JSON fixture data
//! (`parse_geometry`), fed straight into the live `BrepKernel` to mint real geometry handles, and
//! never persisted or re-exposed as document state (`CadSnapshot` now composes real
//! `s.stdio.semio.model` children instead; see that schema file's own doc comment). This mirrors
//! the design corrigendum's "ephemeral working representation... dropped when the call returns"
//! rule for `EngineRep`-class types — the same class of transient bridge this module's sibling
//! (`step_text` ↔ `SemioBrepSnapshot`, in `🚪️io/🦀️.rs`) already uses for STEP.

use protocol::DslValue;
use semio_framework_plugin::{ArtifactSerializer, MeshData};
use semio_framework_3d::brep::engine::mesh_data_from_mesh_transfer;
use semio_framework_3d::brep::engine::{Brep, BrepKernel, GeometryHandle, Vec3};
use std::collections::HashMap;
// 🌉️ Ticket 26/08/11/SEMIO-ARTIFACT-UNIFIED-IMPORT-EXPORT-AND-MEDIA-FORMAT-RETIREMENT W5a: the
// hand-rolled `v`/`f`-only OBJ writer this file used to feed the kernel's own `import_obj` reader
// is now stdio's real `semio/mesh` → `obj` codec (`SemioMeshToObj` + `obj::engine::encode_obj`) —
// same real mesh→OBJ encoder `⚙️engine/🦀️.rs`'s `export_solids_as` now uses, no
// reimplementation.
use semio_s_artifact_stdio_obj::standards::v3_0::engine::encode_obj;
use semio_s_artifact_stdio_semio::standards::v1::subsets::base::schema::geometry::{SemioPoint3, SemioQuaternion, SemioTransform};
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::export::serializers::artifacts::obj::v3_0::any::SemioMeshToObj;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::{SemioMesh, SemioMeshSnapshot, SemioPrimitive, SemioTopology, STDIO_SEMIOMESH_DOCUMENT_SCHEMA};
use semio_s_artifact_stdio_semio::standards::v1::subsets::model::schema::snapshot::{ElementClass, GeometryRef, SemioModelElement, SemioModelSnapshot, STDIO_SEMIOMODEL_DOCUMENT_SCHEMA};

//#region 🔖️EphemeralImportTypes
/// 🧱️ EPHEMERAL — never persisted, never part of `ArtifactSchema`. See module doc comment.
#[derive(Clone, Debug, Default, PartialEq, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub(crate) struct CadGeometry {
    #[value(default)]
    pub anchors: Vec<DslValue>,
    #[value(default)]
    pub vertices: Vec<CadVertex>,
    #[value(default)]
    pub edges: Vec<CadEdge>,
    #[value(default)]
    pub wires: Vec<CadWire>,
    #[value(default)]
    pub faces: Vec<CadFace>,
    #[value(default)]
    pub shells: Vec<CadShell>,
    #[value(default)]
    pub solids: Vec<CadSolid>,
}

#[derive(Clone, Debug, PartialEq, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub(crate) struct CadVertex {
    pub id: String,
    pub position: [f64; 3],
}

/// 📐️ One edge's curve. `kind` is the family (`line`/`arc`/`circle`/`ellipse`/`nurbs`); every other
/// field is that family's parameters, exactly as the TypeScript `EdgeCurve`
/// (`✏️s/🔨️modules/🌐️spatial-kernel/⚙️engine/🧮️preview/🟦️.ts`) carries them.
///
/// 🩸️ Until ticket 26/09/17 packet W14g this struct carried ONLY `kind`, so every curved edge
/// degraded to its two boundary vertices wherever the editor tessellated one — a circle picked and
/// drew as a single chord where React's `edgeSamplePoints` draws 64 samples
/// (`📓️w2f-cad-spatial-editor-wgpu.md` §5.2).
#[derive(Clone, Debug, Default, PartialEq, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub(crate) struct CadEdgeCurve {
    pub kind: String,
    /// ⭕️ `arc`/`circle` centre.
    #[value(default)]
    pub center: Option<[f64; 3]>,
    /// ⭕️ `circle`/`ellipse` plane normal.
    #[value(default)]
    pub normal: Option<[f64; 3]>,
    /// ⭕️ `circle` radius.
    #[value(default)]
    pub radius: Option<f64>,
    /// 🥚️ `ellipse` major axis direction and the two radii.
    #[value(default)]
    pub major_axis: Option<[f64; 3]>,
    #[value(default)]
    pub major_radius: Option<f64>,
    #[value(default)]
    pub minor_radius: Option<f64>,
    /// 📈️ `nurbs` poles (control points, or interpolation points when `through`).
    #[value(default)]
    pub poles: Vec<[f64; 3]>,
    #[value(default)]
    pub degree: Option<u32>,
    #[value(default)]
    pub through: bool,
    /// 📍️ An ALREADY-SAMPLED polyline, when the producer tessellated the curve itself. It wins over
    /// every parameter above, so an importer that has the kernel's own tessellation in hand never
    /// has to round-trip it through the parametric families.
    #[value(default)]
    pub points: Vec<[f64; 3]>,
}

