//#region 🌉️GeometryBridges
// 🐛️ Relocated from the deleted `⚙️engine/🦀️.rs` -- foreign-format(bytes/struct)-to-
// cad-document conversions are deserialization (rule 5). Kept reachable at THIS exact path
// (`crate::io::{cad_document_from_dwg, cad_document_from_mesh,
// cad_mesh_from_document}`) because two OTHER plugins import them at the artifact-level (not
// through an app-internal engine): 🎪️demonstrator/🎪️panes/📐️koordinator and 💠️lowpoly's schema.
pub fn unwrap_spatial_load_payload(raw: &DslValue) -> Option<DslValue> {
    if raw.get("modelSpace").is_some() {
        return raw.get("modelSpace").cloned();
    }
    if raw.get("model").is_some() {
        return raw.get("model").cloned();
    }
    if raw.get("raw").is_some() {
        return raw.get("raw").cloned();
    }
    Some(raw.clone())
}

/// 🌉 Real per-pane object extraction from a `spatial.modelspace`/`spatial.model` payload — the
/// SAME fixture-import machinery (`geometry_import::parse_geometry` + `objects_from_host_snapshot_model`)
/// the Concrete Forest Left quad fixture is built from (`crate::editor::cad::forest_working_scene`),
/// since both are the identical `spatial.model`-shaped wire form. A `spatial.modelspace` payload
/// wraps zero or more `{id|modelDefinitionId, model}` entries in `models[]`; a bare `spatial.model`
/// payload IS one implicit entry. Each entry that resolves to a known `CadPaneId` and carries real
/// objects gets its own real `SemioModelSnapshot` minted (`geometry_import::semio_model_snapshot_from_objects`)
/// and composed as that pane's `CadModelChild` (`crate::cad_model_child_handle`) —
/// panes with no objects, or an id this document doesn't recognize, are left `None` rather than
/// fabricating an empty child. Ticket `26/08/12/UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM` wave 3.
pub fn scene_from_spatial_payload(payload: &DslValue) -> Option<crate::CadSnapshot> {
    use crate::standards::v1::subsets::any::io::geometry_import::{objects_from_host_snapshot_model, parse_geometry, semio_model_snapshot_from_objects};
    use crate::standards::v1::subsets::any::schema::inferences::{cad_brep_kernel, default_document, CAD_MODEL_DEFINITION_SHAPE};
    use crate::{cad_model_child_handle, cad_pane_from_model_definition_id, CadPaneId};
    let schema = payload.get("schema").and_then(|value| value.as_str());
    if schema != Some("spatial.modelspace") && schema != Some("spatial.model") {
        return None;
    }
    let mut document = default_document();
    let owned_models: Vec<DslValue>;
    let models: Vec<&DslValue> = if schema == Some("spatial.modelspace") {
        payload.get("models").and_then(DslValue::as_array).map(|entries| entries.iter().collect()).unwrap_or_default()
    } else {
        owned_models = vec![payload.clone()];
        owned_models.iter().collect()
    };
    for entry in models {
        let model_definition_id = entry.get("id").and_then(DslValue::as_str).or_else(|| entry.get("modelDefinitionId").and_then(DslValue::as_str)).unwrap_or(CAD_MODEL_DEFINITION_SHAPE);
        let Some(pane) = cad_pane_from_model_definition_id(model_definition_id) else {
            continue;
        };
        let model_value = entry.get("model").unwrap_or(entry);
        let Some(objects_value) = model_value.get("objects").and_then(DslValue::as_array) else {
            continue;
        };
        if objects_value.is_empty() {
            continue;
        }
        let geometry = parse_geometry(model_value.get("geometry"));
        let mut kernel = cad_brep_kernel();
        let objects = objects_from_host_snapshot_model(&mut kernel, objects_value, &geometry);
        if objects.is_empty() {
            continue;
        }
        let model = semio_model_snapshot_from_objects(&objects);
        let content_json = semio_framework_pack_json::to_json_string(&model);
        let handle = Some(cad_model_child_handle(pane, &content_json));
        match pane {
            CadPaneId::Shape => document.shape_model = handle,
            CadPaneId::Building => document.building_model = handle,
            CadPaneId::Energy => document.energy_model = handle,
            CadPaneId::StructureClassic => document.structure_classic_model = handle,
        }
    }
    Some(document)
}

pub fn cad_mesh_from_document(doc: &DslValue) -> Result<semio_framework_plugin::MeshData, String> {
    let scene: crate::CadSnapshot = protocol::FromValue::from_value(doc.clone()).map_err(|err: protocol::ValueError| err.to_string())?;
    Ok(crate::standards::v1::subsets::any::schema::inferences::export_mesh_from_scene(&scene))
}

/// 🌉 One `CadObject` per non-empty DWG layer — filters `drawing` down to that layer's entities and
/// tessellates them via the existing `dwg_drawing_to_mesh` merge (reused verbatim, not
/// reimplemented), then imports the result into the live kernel through `geometry_import::cad_object_from_mesh`
/// — the identical OBJ-text bridge every other native-geometry import path in this file already
/// uses. A layer with no entities (or none that triangulate) contributes no object — never a
/// fabricated placeholder.
pub fn cad_working_scene_from_dwg(drawing: &semio_s_artifact_stdio_dwg::DwgDrawing) -> crate::CadWorkingScene {
    use crate::standards::v1::subsets::any::io::geometry_import::cad_object_from_mesh;
    use crate::standards::v1::subsets::any::schema::inferences::{cad_brep_kernel, next_cad_id};
    let mut kernel = cad_brep_kernel();
    let objects = drawing
        .layers
        .iter()
        .enumerate()
        .filter_map(|(layer_index, layer)| {
            let filtered = semio_s_artifact_stdio_dwg::DwgDrawing { layers: drawing.layers.clone(), entities: drawing.entities.iter().filter(|entity| entity.layer == layer_index).cloned().collect(), extmin: drawing.extmin, extmax: drawing.extmax };
            if filtered.entities.is_empty() {
                return None;
            }
            let mesh = semio_s_artifact_stdio_dwg::dwg_drawing_to_mesh(&filtered);
            if mesh.indices.is_empty() || mesh.positions.is_empty() {
                return None;
            }
            Some(cad_object_from_mesh(&mut kernel, next_cad_id("object"), layer.name.clone(), "spatial.shape.imported", &mesh))
        })
        .collect();
    crate::CadWorkingScene { objects, ..Default::default() }
}

/// 🌉 Real per-layer DWG import: every non-empty layer becomes a real `CadObject`
/// (`cad_working_scene_from_dwg`), wrapped into a `SemioModelSnapshot` and minted as a
/// deterministic, content-addressed `shape_model` CHILD HANDLE (`cad_model_child_handle`) — the
/// same "mint the child, dispatch create-<pane>-model against the result" two-step gesture
/// `scene_from_spatial_payload` documents, done here for the ONE piece (the child's own content) a
/// pure function CAN produce. An empty drawing (no layer contributes real geometry) mints no
/// child, matching `scene_from_spatial_payload`'s "no fabricated child" rule. Ticket
/// `26/08/12/UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM` wave 3.
pub fn cad_document_from_dwg(drawing: &semio_s_artifact_stdio_dwg::DwgDrawing) -> Result<DslValue, String> {
    use crate::standards::v1::subsets::any::io::geometry_import::semio_model_snapshot_from_objects;
    use crate::standards::v1::subsets::any::schema::inferences::default_document;
    use crate::{cad_model_child_handle, CadPaneId};
    let working = cad_working_scene_from_dwg(drawing);
    let mut document = default_document();
    if !working.objects.is_empty() {
        let model = semio_model_snapshot_from_objects(&working.objects);
        let content_json = semio_framework_pack_json::to_json_string(&model);
        document.shape_model = Some(cad_model_child_handle(CadPaneId::Shape, &content_json));
    }
    Ok(protocol::ToValue::to_value(&document))
}

/// ⚠️ See `scene_from_spatial_payload`'s doc comment — same documented gap for a `MeshImporter`
/// (GLB) payload.
// 🌉️ `_mesh` is unused (framework `MeshDocumentImporter` registration in the crate root
// `🦀️.rs` requires this exact shape). Return type is `dsl::os_pack::json::Value`, NOT `DslValue`:
// this function is registered as
// `MeshDocumentImporter = fn(&MeshData) -> Result<dsl::os_pack::json::Value, String>`
// (`🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🦀️.rs`), a genuine framework-owned boundary
// type out of this plugin's write scope. Bridged once, at this exact boundary, from a `DslValue`
// built the normal way via `protocol::json::from_dsl_value`.
pub fn cad_document_from_mesh(_mesh: &semio_framework_plugin::MeshData) -> Result<semio_framework_pack_json::Value, String> {
    use crate::standards::v1::subsets::any::schema::inferences::default_document;
    Ok(semio_framework_pack_json::from_dsl_value(&protocol::ToValue::to_value(&default_document())))
}
