const FILL_RUN_FIXTURE: &str = include_str!("../../🧫️fixtures/🎞️fill-run.json");

fn fixture() -> Value {
    let fixture: Value = serde_json::from_str(FILL_RUN_FIXTURE).expect("fill run fixture parses");
    assert_eq!(fixture["schema"], "s.puzzle2d.fill-run.v1");
    fixture
