//#region 🔖️PaneCamera
const PUZZLE2D_VIEWPORT_REF_SHORT_PX: f64 = 640.0;
const PUZZLE2D_VIEWPORT_MARGIN: f64 = 0.18;
const PUZZLE2D_VIEWPORT_FRAMING_HALF_SPAN_SCALE: f64 = 2.25;
const PUZZLE2D_VIEWPORT_ZOOM_BOOST: f64 = 2.5;

fn puzzle2d_pane_zoom_scale(pane: &str) -> f64 {
    match pane {
        detail::WINDOW_KIND_ID => detail::ZOOM_SCALE,
        selection::WINDOW_KIND_ID => selection::ZOOM_SCALE,
        _ => overview::ZOOM_SCALE,
    }
}

fn puzzle2d_clamp_zoom(value: f64) -> f64 {
    value.clamp(BOARD_CAMERA_ZOOM_MIN, BOARD_CAMERA_ZOOM_MAX)
}

/// 📐️ World-space center and half-span of every node's extent (circle radius or rectangle half-size), used to frame pane cameras.
fn puzzle2d_fixture_world_bounds(fixture: &Value) -> (f64, f64, f64) {
    let mut min_x = f64::INFINITY;
    let mut min_y = f64::INFINITY;
    let mut max_x = f64::NEG_INFINITY;
    let mut max_y = f64::NEG_INFINITY;
    for node in fixture_nodes(fixture) {
        let (Some(x), Some(y)) = (node.get("x").and_then(|value| value.as_f64()), node.get("y").and_then(|value| value.as_f64())) else {
            continue;
        };
        let (half_w, half_h) = if node.get("shape").and_then(|value| value.as_str()) == Some("rectangle") {
            (node.get("width").and_then(|value| value.as_f64()).unwrap_or(48.0) * 0.5, node.get("height").and_then(|value| value.as_f64()).unwrap_or(48.0) * 0.5)
        } else {
            let radius = node.get("radius").and_then(|value| value.as_f64()).unwrap_or(24.0);
            (radius, radius)
        };
        min_x = min_x.min(x - half_w);
        max_x = max_x.max(x + half_w);
        min_y = min_y.min(y - half_h);
        max_y = max_y.max(y + half_h);
    }
    if !min_x.is_finite() {
        return (0.0, 0.0, 400.0);
    }
    let half_span = (max_x - min_x).max(max_y - min_y).max(1.0) * 0.5;
    ((min_x + max_x) * 0.5, (min_y + max_y) * 0.5, half_span)
}

/// 📷️ Triptych camera for a pane: overview is zoomed out and centered on the fixture, detail zooms
/// into the last-placed node, selection frames a lower-left quadrant — mirrors the pre-migration
/// `puzzle2dPlayTriptychCameraForPane`.
pub fn puzzle2d_pane_camera(fixture: &Value, runtime: &Puzzle2dPlayRuntime, pane: &str) -> (f64, f64, f64) {
    let (camera_x, camera_y, camera_zoom) = runtime_camera(runtime);
    if pane == overview::WINDOW_KIND_ID {
        return (camera_x, camera_y, puzzle2d_clamp_zoom(camera_zoom));
    }
    let (cx, cy, half_span) = puzzle2d_fixture_world_bounds(fixture);
    let usable = PUZZLE2D_VIEWPORT_REF_SHORT_PX * (1.0 - 2.0 * PUZZLE2D_VIEWPORT_MARGIN);
    let world_span = (2.0 * half_span * PUZZLE2D_VIEWPORT_FRAMING_HALF_SPAN_SCALE).max(1.0);
    let base_zoom = puzzle2d_clamp_zoom((usable / world_span) * PUZZLE2D_VIEWPORT_ZOOM_BOOST);
    let zoom = puzzle2d_clamp_zoom(base_zoom * puzzle2d_pane_zoom_scale(pane));
    match pane {
        detail::WINDOW_KIND_ID => {
            let nodes = fixture_nodes(fixture);
            let detail_node = nodes.get(nodes.len().saturating_sub(1).min(42));
            let x = detail_node.and_then(|node| node.get("x")).and_then(|value| value.as_f64()).unwrap_or(cx) + camera_x * 0.02;
            let y = detail_node.and_then(|node| node.get("y")).and_then(|value| value.as_f64()).unwrap_or(cy) + camera_y * 0.02;
            (x, y, zoom)
        }
        selection::WINDOW_KIND_ID => (cx - half_span * 0.28 + camera_x * 0.06, cy + half_span * 0.22 + camera_y * 0.05, zoom),
        _ => (cx + camera_x * 0.04, cy + camera_y * 0.03, zoom),
    }
}
//#endregion 🔖️PaneCamera

//#region 🔖️Canvas
/// 🗄️ Caches the last serialized fixture keyed by an fnv1a hash of the raw `document_json` it came
/// from, so the overview/detail/selection panes of the same `refreshUi` tick reuse one `String`
/// instead of each re-serializing the whole fixture graph.
fn cached_fixture_json(_document_json: &str, fixture: &Value) -> String {
    fixture.to_string()
}

/// 💡️ How many placement candidates ONE handle-suggestions popup publishes. The surface doc it rides
/// is fixed-capacity and a richly catalogued handle resolves arbitrarily many collision-free
/// candidates, so an unbounded list would make the whole board render of that window fail closed the
/// moment the popup opened. It is also the interaction answer: a picker read at a glance shows a
/// bounded page, and `cycleBrushCandidate` walks the rest.
pub const PUZZLE2D_SUGGESTION_MENU_CANDIDATE_PAGE: usize = 8;

/// 💡️ The open popup's wire record — `None` whenever this window has none. Candidate rows are the
/// SAME page the armed brush cycles (`runtime.brush_candidates`), decorated with the node kind's own
/// icon and colour so the picker reads like the board it paints onto.
fn puzzle2d_suggestion_menu_json(envelope: &Puzzle2dScene, glyph_catalogs_json: &str) -> Option<String> {
    let menu = envelope.runtime.suggestion_menu.as_ref()?;
    let catalogs: Value = serde_json::from_str(glyph_catalogs_json).unwrap_or(Value::Null);
    let node_kinds = catalogs.get("nodeKinds").and_then(Value::as_array).map_or(&[][..], |rows| rows.as_slice());
    let candidates: Vec<Value> = envelope
        .runtime
        .brush_candidates
        .iter()
        .take(PUZZLE2D_SUGGESTION_MENU_CANDIDATE_PAGE)
        .enumerate()
        .map(|(index, candidate)| {
            let node_kind = candidate.get("nodeKind").and_then(|value| value.as_str()).or_else(|| candidate.as_str()).unwrap_or("kind");
            let handle_index = candidate.get("targetHandleIndex").and_then(|value| value.as_i64()).unwrap_or(0);
            let row = node_kinds.iter().find(|row| row.get("id").and_then(Value::as_str) == Some(node_kind));
            json!({
                "index": index,
                "nodeLabel": node_kind,
                "handleLabel": format!("handle {handle_index}"),
                "icon": row.and_then(|row| row.get("icon")).and_then(Value::as_str),
                "color": row.and_then(|row| row.get("color")).and_then(Value::as_str),
            })
        })
        .collect();
    Some(
        json!({
            "open": true,
            "x": menu.x,
            "y": menu.y,
            "windowId": menu.window_id,
            "handleId": menu.handle_id,
            "hoveredIndex": envelope.runtime.brush_candidate_index,
            // 🔎️ Pending only while the slot has resolved nothing AND still names the handle it opened
            // on; an empty page on a resolved slot is the polite refusal, not a spinner that never ends.
            "pending": candidates.is_empty() && envelope.runtime.brush_candidate_source_handle_id.is_empty(),
            "candidates": candidates,
        })
        .to_string(),
    )
}

/// 🖼️ The board-2d scene one pane publishes. Public so the laws can assert what reaches the client
/// (hover id, suggestion popup) without decoding a rendered surface node.
pub fn puzzle2d_board_scene(document_json: &str, envelope: &Puzzle2dScene, pane: &str) -> Board2dScene {
    let fixture = &envelope.fixture;
    let (camera_x, camera_y, zoom) = puzzle2d_pane_camera(fixture, &envelope.runtime, pane);
    let camera_json = json!({ "x": camera_x, "y": camera_y, "zoom": zoom }).to_string();
    let glyph_catalogs_json = crate::editor::puzzle2d::board_kind_catalogs_json_or_inferred(fixture).unwrap_or_else(|| "{}".into());
    // 🕹️ The framework-owned `vortex` selection, resolved once per render by
    // `Puzzle2dPlayApp::render_with_request_context`, echoes back to the board engine here.
    let selection_json = envelope.interaction.selection_json();
    let brush_weights_json = serde_json::to_string(&json!({
        "nodeWeights": envelope.runtime.node_kind_weights,
        "handleWeights": envelope.runtime.handle_kind_weights,
    }))
    .unwrap_or_else(|_| "{}".into());
    let placement_compatibility_json = fixture.get("meta").and_then(|value| value.get("kindCompatibility")).or_else(|| fixture.get("kindCompatibility")).map_or_else(|| "[]".into(), |value| value.to_string());
    let lod_mode = envelope.runtime.lod_mode_by_pane.get(pane).cloned().unwrap_or_else(|| PUZZLE2D_LOD_MODE_AUTOMATIC.to_string());
    let suggestion_menu_json = puzzle2d_suggestion_menu_json(envelope, &glyph_catalogs_json);
    Board2dScene {
        fixture_json: cached_fixture_json(document_json, fixture),
        camera_json,
        glyph_catalogs_json,
        selection_json,
        highlighted_ids_json: envelope.interaction.referenced_json(),
        interactive: pane == overview::WINDOW_KIND_ID,
        // 🐁️ The framework-owned `vortex` hover, echoed into every pane: the interactive overview
        // publishes it from its own pointer raycast, the detail/selection panes and the outliner
        // tree rows read it back, so hovering anywhere highlights the same entity everywhere.
        hovered_id: envelope.interaction.hovered_id(),
        active_utility: Some(envelope.active_utility.clone()),
        selection_method: "rectangle".into(),
        grid_visible: envelope.runtime.grid_visible,
        grid_snap_enabled: envelope.runtime.grid_snap_enabled,
        grid_factor: envelope.runtime.grid_factor,
        selectable_nodes: envelope.runtime.selectable_kinds.nodes,
        selectable_edges: envelope.runtime.selectable_kinds.edges,
        selectable_handles: envelope.runtime.selectable_kinds.handles,
        suggestion_offset: envelope.runtime.suggestion_offset,
        brush_weights_json,
        placement_compatibility_json,
        lod_mode,
        transform_flags: Some(json!({ "move": envelope.runtime.transform_move, "rotate": envelope.runtime.transform_rotate }).to_string()),
        // 🖍️ The Area Brush's own W/H steppers as world extent — what ONE click paints. The regions
        // themselves ride the fixture lane (the document's `targetRegions`), not a second carrier.
        area_brush_size: Some({
            let (width, height) = crate::editor::puzzle2d::puzzle2d_area_brush_extent_world(&envelope.runtime);
            json!({ "width": width, "height": height }).to_string()
        }),
        domain_id: Some(crate::editor::puzzle2d::PUZZLE2D_INTERACTION_DOMAIN.into()),
        suggestion_menu_json,
        tool_run_trace: None,
        lanes: Vec::new(),
    }
}

/// 🖼️ The board-2d surface node for one pane — bound by each window's own `render()`. The fixture rides
/// as its own paged lane carrier (`Board2dSceneLane::Fixture`), so a 180-node board is bounded by its
/// carrier pages instead of by the 32 KiB surface doc that refused it outright.
pub fn render_canvas(document_json: &str, envelope: &Puzzle2dScene, pane: &str) -> semio_framework_plugin::UiAssemblyResult<semio_framework_plugin::BuiltNode> {
    let scene = puzzle2d_board_scene(document_json, envelope, pane);
    semio_framework_plugin::scene_surface(&format!("{PUZZLE2D_PLAY_SURFACE_ID}.{pane}"), semio_framework_ui_contract::SurfaceKind::Board2d, &scene)
}
//#endregion 🔖️Canvas

//#region 🔖️Engagement
/// 🤝️ The engagement HUD for one pane: a text command line plus a node/edge/LOD status readout.
pub fn puzzle2d_engagement(envelope: &Puzzle2dScene, host: &BoardHost, pane: &str, labels: &Puzzle2dLabels) -> WindowEngagement {
    let overlay: Value = serde_json::from_str(&host.overlay_paint_state_json()).unwrap_or(Value::Null);
    let pane_lod_mode = envelope.runtime.lod_mode_by_pane.get(pane).map_or(PUZZLE2D_LOD_MODE_AUTOMATIC, String::as_str);
    let lod = overlay.get("lod").and_then(|value| value.as_str()).unwrap_or(if pane_lod_mode == PUZZLE2D_LOD_MODE_AUTOMATIC { "auto" } else { pane_lod_mode });
    let node_count = fixture_nodes(&envelope.fixture).len();
    let edge_count = fixture_edges(&envelope.fixture).len();
    let input_value = envelope.runtime.engagement_input_by_pane.get(pane).cloned().unwrap_or_default();
    let placeholder = match envelope.active_utility.as_str() {
        "brush" => "Brush",
        _ => "select, brush, fill <n>, clear, move <dx> <dy>, rotate <deg>, scale <f>, connect <handle> <handle>",
    };
    WindowEngagement {
        session_active: Some(envelope.active_utility != "select"),
        input: Some(WindowEngagementInput {
            id: Some("puzzle2d-engagement".into()),
            value: Some(input_value),
            placeholder: Some(placeholder.into()),
            disabled: None,
            on_change: Some(puzzle2d_action("engagementInput", Some(semio_framework::dsl_value!({ "pane": pane })))),
            on_submit: Some(puzzle2d_action("engagementSubmit", Some(semio_framework::dsl_value!({ "pane": pane })))),
            on_repeat_last: Some(puzzle2d_action("engagementRepeatLast", Some(semio_framework::dsl_value!({ "pane": pane })))),
            on_abort: Some(puzzle2d_action("engagementAbort", Some(semio_framework::dsl_value!({ "pane": pane })))),
        }),
        control: None,
        controls: None,
        status: Some(vec![WindowEngagementStatus { id: "puzzle2d-board-status".into(), text: format!("{node_count} {} · {edge_count} {} · {} {lod}", labels.nodes.as_str(), labels.edges.as_str(), labels.lod.as_str()) }]),
        // 🧰️ The select/brush/fill switcher lives in the framework utility bar (declared via `.utility` +
        // `.window_kind_utilities`), so the engagement no longer duplicates it as toggle options.
        options: None,
        possible_engagements: None,
    }
}
//#endregion 🔖️Engagement

pub(crate) mod context {
    use super::super::*;
    use semio_framework_plugin::artifact_app_laws::{meta, new_app_with_registry};
    use semio_framework_plugin::{EditorApp, InvocationResult, PluginApp, VcsArtifactApp, ViewModel, ViewWindowInstance};

    /// ✏️ Adapts `create_en1992_app`'s `AppDefinition` (contract §2.4) into the `App { definition,
    /// examples }` shape `context::new_app_with_registry` still expects (framework test context gap,
    /// see w0-f-report.md gap 3 — swap for the canonical helper once it lands).
    pub fn en1992_manifest_for_tests() -> semio_framework_plugin::App {
        semio_framework_plugin::App { definition: create_en1992_app(), examples: Vec::new() }
    }

    pub type NormApp = VcsArtifactApp<EditorApp<En1992PlayApp>>;

    /// ð§¬ï¸ A wrapper carrying the real registry so kind discipline (View-emits-operations rejection) runs.
    pub async fn app_with_registry() -> NormApp {
        let mut app = new_app_with_registry::<EditorApp<En1992PlayApp>>(en1992_manifest_for_tests).await;
        semio_framework::io::resolve_ready(app.bind_instance_id(meta("local").instance_id));
        app
    }

    /// 🧹️ Closes every store the wrapper opened. A live `ArtifactStore` asserts in `Drop` unless it was
    /// driven to its terminal-empty shallow shell, so every fixture that mounts an app must end here.
    pub fn close(app: &mut NormApp) {
        semio_framework_plugin::artifact_app_laws::close_registered_fixture_app(app);
    }

    pub async fn dispatch(app: &mut NormApp, command: En1992Command) -> InvocationResult {
        let mut action_meta = meta("local");
        if command.command_id() == "setSelectedCheckIndex" {
            action_meta.view_state = Some(ViewModel {
                window_id: Some(results::WINDOW_RESULTS.into()),
                focused_window_id: Some(results::WINDOW_RESULTS.into()),
                window_instances: vec![ViewWindowInstance { id: results::WINDOW_RESULTS.into(), window_kind_id: results::WINDOW_RESULTS.into() }],
                ..ViewModel::new(semio_framework_ui_locale::Locale::En, semio_framework_ui_locale::Terminology::Native)
            });
        }
        let result = app.dispatch_typed(command, &action_meta).await.expect("dispatch");
        settle(app).await;
        result
    }

    /// 🔁️ Drives one dispatched typed operation to quiescence the way the plugin host does, draining
    /// EVERY result page: a bare `maintenance_step` loop retires nothing and turns a publication fault
    /// into a silent timeout, which is exactly how ticket 26/09/18 slice B2b lost the real cause.
    pub async fn settle(app: &mut NormApp) {
        semio_framework_plugin::artifact_app_laws::settle_registered_typed_operation(app, meta("local").instance_id).await.expect("settle the typed operation");
    }

    pub async fn render(app: &mut NormApp, body_key: &str) -> String {
        semio_framework_plugin::artifact_app_laws::project_and_retire_fixture_tree(app.render(body_key, None, &ViewModel::new(semio_framework_ui_locale::Locale::En, semio_framework_ui_locale::Terminology::Native)).await.expect("render")).expect("render projection")
    }
}

use super::*;
use semio_framework_plugin::PluginApp;

#[test]
fn retained_command_dispositions_match_the_language_neutral_oracle() {
    crate::app_surface::retained_disposition_oracle::assert_fixture(VARIANT);
    let definition = create_en1992_app();
    let mut classified = 0usize;
    for window in definition.window_kinds.iter() {
        // 🕹️ `window.actions` holds only what a window kind claims FOR ITSELF. Since the app-wide
        // roster stopped being cloned into every window kind, the dispatchable set of a window is
        // `semio_framework::window_kind_actions` — the same predicate the framework's own
        // command-bridge law uses. Norm declares all three retained tools at app level, so reading
        // `window.actions` here saw an empty roster.
        let dispatchable = semio_framework::window_kind_actions(&definition, window);
        for id in crate::app_surface::NORM_RETAINED_TOOL_IDS {
            let action = dispatchable.iter().find(|action| action.id == *id).unwrap_or_else(|| panic!("window {} must dispatch {id}", window.id));
            assert_eq!(action.semantics.execution.interactive_job, InteractiveJobClassification::Migrated);
            classified += 1;
        }
    }
    assert_eq!(classified, definition.window_kinds.len() * crate::app_surface::NORM_RETAINED_TOOL_IDS.len());
}

//#region ðï¸CommandSurface
/// ð¯ï¸ One value per `En1992Command` row â the whole-command-surface laws below iterate it, so a new row
/// that is not listed here fails `command_ids_cover_every_row`.
fn every_command() -> Vec<En1992Command> {
    vec![
        En1992Command::ReplaceSnapshot(set_snapshot::ReplaceSnapshot { snapshot: En1992Snapshot::default() }),
