        view_state: &semio_framework_plugin::ViewModel,
    ) -> semio_framework_plugin::UiAssemblyResult<semio_framework_plugin::ComponentTree> {
        let preview = match doc.render_operation() {
            Some(operation) => owner
                .with_mut::<DrawingInstanceOperationOwner, _>(|owner| Ok(owner.preview_projection(operation.canonical_base_revision, drawing_active_utility(view_state))))
                .map_err(|error| semio_framework_plugin::PluginAssemblyError::new("drawing.gesture.preview-owner", error.message))?
                .unwrap_or_default(),
            None => DrawingGesturePreview::default(),
        };
        render_drawing_body(body_key, doc.snapshot, &canvas_window::config::current(cfg), &preview, &[], &[], view_state)
    }

    fn render_with_request_context(
        owner: &semio_framework_plugin::ArtifactInstanceOperationOwnerHandle,
        body_key: &str,
        doc: &ArtifactView<'_, DrawingSnapshot>,
        cfg: &ConfigView<'_, NoConfig>,
        view_state: &semio_framework_plugin::ViewModel,
        _transient: &semio_framework_plugin::TransientView<'_, semio_framework_plugin::NoTransient>,
        interaction: &InteractionView<'_>,
    ) -> semio_framework_plugin::UiAssemblyResult<semio_framework_plugin::ComponentTree> {
        if body_key == DRAWING_PLAY_BODY_PROPERTIES {
            return properties_panel::render(doc.snapshot, &interaction.selection(DRAWING_INTERACTION_DOMAIN).ids, semio_framework_plugin::resolve_labels::<DrawingPlayLabels>(view_state), &semio_framework_plugin::TreeWindows::for_body(view_state, body_key)).map(semio_framework_plugin::built_to_component_tree);
        }
        let preview=match doc.render_operation() {
            Some(operation)=>owner.with_mut::<DrawingInstanceOperationOwner,_>(|owner|Ok(owner.preview_projection(operation.canonical_base_revision,drawing_active_utility(view_state))))
                .map_err(|error|semio_framework_plugin::PluginAssemblyError::new("drawing.gesture.preview-owner",error.message))?.unwrap_or_default(),
            None=>DrawingGesturePreview::default(),
        };
        render_drawing_body(body_key,doc.snapshot,&canvas_window::config::current(cfg),&preview,&interaction.selection(DRAWING_INTERACTION_DOMAIN).ids,&interaction.selection(DRAWING_POINT_DOMAIN).ids,view_state)
    }

    fn window_engagements(doc: &ArtifactView<'_, DrawingSnapshot>, _cfg: &ConfigView<'_, NoConfig>, view_state: &semio_framework_plugin::ViewModel) -> HashMap<String, WindowEngagement> {
        let Some(window_id) = view_state.window_id.clone() else { return HashMap::new() };
        // 🧮️ The status row reports the LIVE top-level layer count (selection is framework-owned and not
        // visible from this view, so it stays at the framework's interaction domain); it used to be a
        // hard-coded "0 layers · 0 selected" that no load or edit ever moved.
        let layer_count = doc.snapshot.layers.len();
        let engagement = WindowEngagement {
            session_active: Some(false),
            options: None,
            input: Some(WindowEngagementInput {
                id: Some("drawing-canvas-engagement".into()),
                value: Some(String::new()),
                placeholder: Some("Layer name".into()),
                on_change: Some(drawing_manifest_action("engagementInput")),
                on_submit: Some(drawing_manifest_action("engagementSubmit")),
                disabled: None,
                on_repeat_last: None,
                on_abort: None,
            }),
            control: None,
            controls: None,
            status: Some(vec![WindowEngagementStatus { id: "drawing-layer-count".into(), text: format!("{layer_count} layer{} · 0 selected", if layer_count == 1 { "" } else { "s" }) }]),
            possible_engagements: None,
        };
        HashMap::from([(window_id, engagement)])
    }

    fn window_engagements_with_request_context(
        doc: &ArtifactView<'_, DrawingSnapshot>,
        cfg: &ConfigView<'_, NoConfig>,
        view_state: &semio_framework_plugin::ViewModel,
        transient: &semio_framework_plugin::TransientView<'_, semio_framework_plugin::NoTransient>,
        _interaction: &semio_framework_plugin::app::InteractionView<'_>,
    ) -> HashMap<String, WindowEngagement> {
        let mut engagements = Self::window_engagements(doc, cfg, view_state);
        let Some(window_id) = view_state.window_id.as_ref() else { return HashMap::new() };
        let current = canvas_window::transient::current(transient);
        if let Some(input) = engagements.get_mut(window_id).and_then(|engagement| engagement.input.as_mut()) {
            input.value = Some(current.engagement_input);
        }
        engagements
    }
