#[semio_framework_async_macros::async_test]
async fn maps_layers_blocks_and_entities() {
    let cad = semio_framework_plugin::resolve_ready(SemioCadFromDxf::deserialize(&sample_dxf())).expect("deserialize");
    assert_eq!(cad.layers.len(), 1);
    assert_eq!(cad.layers[0].visible, true);
    assert_eq!(cad.blocks.len(), 1);
    assert_eq!(cad.blocks[0].entities.len(), 1);
    assert!(matches!(cad.blocks[0].entities[0].entity, CadEntity::Line { .. }));
    // circle, insert, ellipse map; 3DFACE (Other, unmodeled kind) is honestly dropped
    assert_eq!(cad.entities.len(), 3);
    assert!(matches!(cad.entities[0].entity, CadEntity::Circle { .. }));
    assert!(matches!(cad.entities[1].entity, CadEntity::Insert { .. }));
    match &cad.entities[2].entity {
        CadEntity::Ellipse { center, major_axis_end, ratio, .. } => {
            assert_eq!(*center, SemioPoint2 { x: 1.0, y: 1.0 });
            assert_eq!(*major_axis_end, SemioPoint2 { x: 4.0, y: 1.0 });
            assert_eq!(*ratio, 0.5);
        }
        other => panic!("expected Ellipse, got {other:?}"),
    }
}

//! 🪣️ Edit-mode tool — Fill: a whole-document generator declared as a framework tool run
//! (`📋️tool-run-contract.md` §2.4, §3.7). The manifest carries its [`ToolRunDefinition`]; the framework
//! injects start/pause/resume/step/abort/finalize/dismiss, owns the provisional placements in its ledger and
//! publishes them as one edit on finalize. This module declares the definition, the count measure (shared
//! configuration the driver watches) and builds the run and revalidate jobs.

use crate::editor::puzzle3d::config::{Puzzle3dConfig, Puzzle3dRuntime};
use crate::editor::puzzle3d::modes::edit::windows::main;
use crate::editor::puzzle3d::precompute::fill::{fill_run_placements, FillPreparationRoots, FillRevalidateJob, FillRunJob, FillRunPlacement, FILL_RUN_OPS_PER_PLACEMENT};
