//#region 🔖️MediaImport
/// 🕳️ Not rewired onto the semio/drawing bridge (see `stdio_gaps` in the W5b ticket report): the
/// drawing subset has no dwg-format io leaf yet (only svg/dxf/pdf), and routing through the
/// DWG artifact's `dwg_drawing_to_svg` + `resolve_ready(io_dispatch(svg→drawing))` round trip would REGRESS this
/// path — `dwg_drawing_to_svg` only walks `LwPolyline` geometry (silently drops `Text` entities)
/// and `DrawNode::Text` has no font-size field to carry DWG's `height`. `ink_block_from_points`/
/// `text_block_from_dwg` below are real domain mappers over already-typed `DwgGeometry` fields
/// (not hand-rolled DWG byte manipulation — `semio_framework::dwg_from_bytes` does the actual
/// byte-level parse), kept as the honest, lossless choice until that bridge exists.
fn ink_block_from_points(ids: &mut crate::schema::NoteIdOwner, points: &[[f64; 2]]) -> NoteBlockNode {
    let mut min_x = f64::INFINITY;
    let mut min_y = f64::INFINITY;
    let mut max_x = f64::NEG_INFINITY;
    let mut max_y = f64::NEG_INFINITY;
    for point in points {
        min_x = min_x.min(point[0]);
        min_y = min_y.min(point[1]);
        max_x = max_x.max(point[0]);
        max_y = max_y.max(point[1]);
    }
    let local_points = points.iter().map(|point| [point[0] - min_x, point[1] - min_y]).collect();
    NoteBlockNode::Ink {
        id: crate::schema::create_note_id(ids, "dwg-ink"),
        name: "Imported Stroke".into(),
        x: min_x,
        y: min_y,
        width: (max_x - min_x).max(1.0),
        height: (max_y - min_y).max(1.0),
        rotation: 0.0,
        visible: true,
        locked: false,
        points: local_points,
        stroke_width: 1.0,
        color: [0.0, 0.0, 0.0, 1.0],
    }
}

fn text_block_from_dwg(ids: &mut crate::schema::NoteIdOwner, at: &[f64; 3], height: f64, rotation: f64, content: &str) -> NoteBlockNode {
    let font_size = if height > 0.0 { height } else { 12.0 };
    let id = crate::schema::create_note_id(ids, "dwg-text");
    let paragraphs = vec![NoteTextParagraph { runs: vec![NoteTextRun { text: content.to_string(), bold: None, italic: None, underline: None, link: None }] }];
    NoteBlockNode::Text {
        content: crate::note_text_child_record(&id, &paragraphs),
        id,
        name: "Imported Text".into(),
        x: at[0],
        y: at[1],
        width: (content.chars().count() as f64 * font_size * 0.6).max(font_size),
        height: font_size * 1.4,
        rotation,
        visible: true,
        locked: false,
        font_size,
        font_weight: "normal".into(),
        align: "left".into(),
    }
}

pub fn note_document_json_from_dwg(drawing: &DwgDrawing) -> Result<Value, String> {
    let mut ids = crate::schema::NoteIdOwner::new(format!("dwg-import:{}", drawing.entities.len()), 0);
    let mut document = crate::schema::empty_note_snapshot();
    document.id = crate::schema::create_note_id(&mut ids, "dwg-import");
    document.title = Some("Imported Drawing".into());
    for entity in &drawing.entities {
        match &entity.geometry {
            DwgGeometry::Line { start, end } => {
                document.blocks.push(ink_block_from_points(&mut ids, &[[start[0], start[1]], [end[0], end[1]]]));
            }
            DwgGeometry::LwPolyline { closed, vertices, .. } => {
                if vertices.len() >= 2 {
                    let mut points = vertices.clone();
                    if *closed {
                        points.push(vertices[0]);
                    }
                    document.blocks.push(ink_block_from_points(&mut ids, &points));
                }
            }
            DwgGeometry::Text { at, height, rotation, content } => {
                document.blocks.push(text_block_from_dwg(&mut ids, at, *height, *rotation, content));
            }
            _ => {}
        }
    }
    serde_json::from_str::<Value>(&semio_framework_pack_json::to_json_string(&document)).map_err(|error| error.to_string())
}
