    <Generation3dSnapshot as protocol::FromValue>::from_value(semio_framework_pack_json::to_dsl_value(&glb_document)).expect("parseable glb projection").retire_cold();

    let stl_bytes = StlExporter.export(&mesh).expect("stl export");
