    #[value(default)]
    pub trace: Vec<Wfc3dFillTraceEvent>,
}

impl Wfc3dFillTickPayload {
    /// 🧮 How many slots already carry a tile.
    pub fn decided_count(&self) -> usize {
        self.assignments.values().filter(|tile| tile.is_some()).count()
    }

    /// 🏁️ The `SetSolve` mutations a successful (or contradictory) finish publishes.
    pub fn into_transient(&self) -> crate::editor::wfc3d::transient::Wfc3dTransient {
        crate::editor::wfc3d::transient::Wfc3dTransient {
            assignments: self
                .assignments
                .iter()
                .filter_map(|(slot, tile)| {
                    tile.as_ref().map(|tile| crate::editor::wfc3d::transient::Wfc3dAssignment {
                        slot_id: slot.clone(),
                        tile_id: tile.clone(),
                    })
                })
                .collect(),
            contradiction: self.contradiction,
        }
    }

    pub fn set_solve_mutations(&self) -> Vec<Wfc3dTransientMutation> {
        let assignments = self
            .assignments
            .iter()
            .filter_map(|(slot_id, tile_id)| {
                tile_id.as_ref().map(|tile_id| crate::editor::wfc3d::transient::Wfc3dAssignment {
                    slot_id: slot_id.clone(),
                    tile_id: tile_id.clone(),
                })
            })
            .collect();
        vec![SetSolve { assignments, contradiction: self.contradiction }.into()]
    }
}

