#[derive(Clone, Copy, Debug)]
pub struct FlowWheelPlan {
    revision: u64,
    expected: [f64; 3],
    next: [f64; 3],
}

impl FlowWheelPlan {
    pub fn camera(&self) -> [f64; 3] {
        self.next
    }
