);
expansion_owner!(GuardedEncoding,
    fn encode_sqlite_snapshot_native(&self, encoding: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<crate::io_schema::IoPayload, String> {
        use semio_framework_value::native_encoding::{NativeEncodeControl, NativeEncodeProgress};
        let limits=control.limits();if self.output_bytes>limits.max_file_bytes{return Err("native fixture exceeds file ceiling".into())}let mut callback=|event:NativeEncodeProgress|control.checkpoint(SqliteSnapshotPhase::EncodeNative,event.completed,event.total).is_ok();let mut native=NativeEncodeControl::new(limits.max_value_bytes,&mut callback);native.begin_stage(self.output_bytes)?;let mut bytes=native.allocate_vec(self.output_bytes)?;CONTROLLED_ENCODER_CALLS.with(|count|count.set(count.get()+1));while bytes.len()<self.output_bytes{let count=65536.min(self.output_bytes-bytes.len());bytes.resize(bytes.len()+count,b'x');native.advance(count)?;}match encoding{SnapshotEncoding::Binary=>Ok(crate::io_schema::IoPayload::Binary(bytes)),SnapshotEncoding::Text=>Ok(crate::io_schema::IoPayload::Text(String::from_utf8(bytes).map_err(|error|error.to_string())?))}
    }
