    let emit=|control:&mut NativeEncodeControl<'_>|if document{crate::os_pack::encode_document_controlled(&spec,&record,&PackEncodeOptions::default(),control)}else{crate::os_pack::encode_record_body_controlled(&spec,&record,&PackEncodeOptions::default(),control)};
    let mut accept=|_|true;let output=emit(&mut NativeEncodeControl::new(maximum,&mut accept)).unwrap();let actual=if document{crate::os_pack::decode_document(&output,&spec,&PackDecodeOptions::default()).unwrap().0}else{crate::os_pack::decode_record_body_exact(&output,&spec,&PackDecodeOptions::default()).unwrap()};assert_eq!(actual,record);let ordinary=if document{crate::os_pack::encode_document(&spec,&record,&PackEncodeOptions::default()).unwrap()}else{crate::os_pack::encode_record_body(&spec,&record,&PackEncodeOptions::default()).unwrap()};assert_eq!(output,ordinary);
    let mut reached=false;let mut callback=|event:NativeEncodeProgress|if event.total==length&&event.completed>=cancel_at&&event.completed<event.total{reached=true;false}else{true};assert!(emit(&mut NativeEncodeControl::new(maximum,&mut callback)).is_err());assert!(reached);
