    /// 26/09/02/PUZZLE-3D-END-TO-END wave B19 found wave B16's two laws green over the latter.
    #[cfg(test)]
    struct HostCallCensus {
        completions: usize,
        history_patches: usize,
        spent: usize,
        parked: Option<usize>,
