                "Baum",
                SurfaceKind::BlockList,
                "list-tree",
                vec![ActionDefinition::bounded_catalog("set-node", LocalizedLabel::native("Set Node", "Knoten setzen"), ActionKind::Mutation)
                    .with_args(vec![
