        pub(crate) code: &'static str,
        pub(crate) detail: &'static str,
    }

    pub(crate) const RUNTIME_CLEANUP_FAULTS: [RuntimeCleanupFault; 19] = [
        RuntimeCleanupFault::Clock,
        RuntimeCleanupFault::ClockRegression,
