impl WorkerPoolConfig {
    pub fn new(process_kind: ProcessKind, cores: usize) -> WorkerPoolConfig {
        WorkerPoolConfig { process_kind, cores, interactive_reserve: matches!(process_kind, ProcessKind::InteractiveNative) }
    }
